/* Victory Park v3. Local teaching prototype: no payment, sending or analytics. */
(() => {
'use strict';
const PROMO='vp.family.v5.promotion', COMPANY='vp.family.v5.company';
const quick=document.body.dataset.checkout==='quick';
// Quick checkout buys the selected rights; missing profile data is checked before riding.
const purchaseOptions=quick?Object.freeze({deferUnknownProfile:true}):undefined;
const KEY='vp.family.v5', ORDER='vp.family.v5.order', LOCK='vp.family.v5.payment', HISTORY='vp.family.v5.orders';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=v=>JSON.parse(JSON.stringify(v)), money=n=>new Intl.NumberFormat('ru-RU').format(n||0)+'\u00a0֏';
const btn=(act,label,data='',cls='btn')=>`<button type="button" class="${cls}" data-action="${act}" ${data}>${label}</button>`;
const note=(s,tone='info')=>`<div class="notice" data-tone="${tone}">${esc(s)}</div>`;
let state,order=null,warning='',familyOpen=false,focusPerson='family',undo=null,busy=false,activeProduct='unlimited',customTarget='',storageAvailable=true,agePerson='',directEntry=false,returnMode='';
let reviewing=false,reviewedToken='',viewingHistory=false,copyFailure=false,editingCompanion=false,resolveScenario='issuance';
let purchaseRouteIssue='',formError='',copyStatus='',scenario='success',promotion=VPC.normalizePromotion(null),ticketPersonId='',accompaniment=null;
let quickRideId='',quickPersonId='',needsProductChoice=false;
try{promotion=VPC.normalizePromotion(JSON.parse(localStorage.getItem(PROMO)||'null'));}catch{}
try {state=VP3.sanitizeState(JSON.parse(localStorage.getItem(KEY)||'null'));} catch {state=VP3.emptyState();storageAvailable=false;warning='Браузер не сохранил выбор. Можно продолжить в этой вкладке.';}
try {const raw=JSON.parse(localStorage.getItem(ORDER)||'null');if(raw){order=VPC.validateOrder(raw);if(!order)warning='Сохранённый образец заказа повреждён. Соберите заказ заново.';}}catch {warning='Предыдущий демо-заказ недоступен. Реальных списаний не было.';}
// Completed receipts open only on explicit history/resume; a new entry always selects a product.
const entryQuery=new URLSearchParams(location.search);
if(order&&['success','declined'].includes(order.status)&&!entryQuery.has('resume')){settlePaidLines(order);order=null;}
familyOpen=!state.party.length;
const rides=()=>state.mode==='real'?VP3.realRides:VP3.demoRides;
const ride=id=>[...VP3.realRides,...VP3.demoRides].find(r=>r.id===id);
const person=id=>state.party.find(p=>p.id===id);
const selected=()=>state.selections[state.mode]||[];
const ageLabel=p=>p.role==='adult'?'18+':p.age===null?'Возраст не указан':p.age===0?'До года':p.age+' лет';
const personLabel=p=>p.label+' · '+ageLabel(p);
const pickerReturn=()=>returnMode==='real'?'attractions.html?mode=real#plan':'attractions.html#plan';
const id=()=> 'v3-'+(crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2,8));
function announce(text){$('#announce').textContent=text;}
function save(){try {localStorage.setItem(KEY,JSON.stringify(state));}catch {storageAvailable=false;warning='Выбор не сохраняется в браузере. При переходе или обновлении он может потеряться.';}}
function savePromotion(){try{localStorage.setItem(PROMO,JSON.stringify(promotion));}catch{storageAvailable=false;warning='Предложение сохранено только в этой вкладке.';}}
function pastOrders(){try{return (JSON.parse(localStorage.getItem(HISTORY)||'[]')||[]).map(VPC.validateOrder).filter(o=>o&&o.status==='success').slice(0,20);}catch{return [];}}
function saveOrder(){
 try {
  if(order)localStorage.setItem(ORDER,JSON.stringify(order));else localStorage.removeItem(ORDER);
  if(order?.status==='success')localStorage.setItem(HISTORY,JSON.stringify([order,...pastOrders().filter(o=>o.id!==order.id)].slice(0,20)));
  return true;
 }catch{storageAvailable=false;warning='Не удалось сохранить заказ в браузере. Сохраните готовые билеты в файл. Текущая покупка остаётся открытой.';return false;}
}
// Receipt navigation is separate from the active payment stored in ORDER.
function storedOrder(){try{return VPC.validateOrder(JSON.parse(localStorage.getItem(ORDER)||'null'));}catch{return null;}}
function settlePaidLines(paid){if(paid?.status!=='success')return;const paidIds=new Set(paid.lines.map(l=>l.id)),remaining=state.cart.lines.filter(l=>!paidIds.has(l.id));if(remaining.length!==state.cart.lines.length){state.cart.lines=remaining;save();}}
function orderURL(id){const url=new URL(location.href);if(id)url.searchParams.set('resume',id);else url.searchParams.delete('resume');try{history.replaceState(history.state,'',url.pathname+url.search+url.hash);}catch{}if(typeof params!=='undefined'){if(id)params.set('resume',id);else params.delete('resume');}}
function restoreOrderView(){
 const active=storedOrder(),requested=new URLSearchParams(location.search).get('resume');viewingHistory=false;
 if(requested){
  const found=active?.id===requested?active:pastOrders().find(o=>o.id===requested);
  if(found){order=found;viewingHistory=found.status==='success';settlePaidLines(found);return;}
  warning='Этот заказ не найден в данном браузере. Откройте сохранённые билеты или исходный браузер.';
 }
 settlePaidLines(active);order=active&&!['success','declined'].includes(active.status)?active:null;
}
function checkoutRoute(file){const query=new URLSearchParams(location.search),next=new URL(file,location.href);for(const key of ['lang','review','picker'])if(query.has(key))next.searchParams.set(key,query.get(key));return next.pathname+next.search;}
function purchases(){const saved=pastOrders();return saved.length?`<details class="purchase-history" id="purchase-history"><summary>Мои покупки (${saved.length})</summary><p class="helper">Последние 20 учебных покупок в этом браузере. На другом устройстве понадобятся сохранённые файлы.</p>${saved.map(o=>`<div class="past-order"><span>${esc(o.id)}<small>${money(o.total)}</small></span>${btn('open-order','Открыть билеты',`data-order="${esc(o.id)}"`,'btn btn-outline')}</div>`).join('')}</details>`:'';}

function update(message){save();render();if(message)announce(message);}
function jump(selector){requestAnimationFrame(()=>$(selector)?.scrollIntoView({block:'start',behavior:'smooth'}));}
function calculateCart(input,promo){return VPC.calculate(input,promo,undefined,purchaseOptions);}
function syncCompanions(){if(order||!VP3.reconcileCompanions)return;accompaniment=VP3.reconcileCompanions(state,purchaseOptions);state=accompaniment.state;}
function audience(){const people=focusPerson==='family'||focusPerson==='all'?state.party:[person(focusPerson)].filter(Boolean);return people;}
function admission(r,p){return VP3.admission?VP3.admission(r,p):{status:VP3.ageHint(r,p).status==='outside'?'blocked':'unknown',reasons:[]};}
function admissionMarkup(r){if(new URLSearchParams(location.search).get('review')!=='1')return '<p class="admission-note">Уточните условия и оплату сопровождения на кассе перед покупкой.</p>';
  if(!r.fictional)return '';
  const people=audience(),checks=people.map(p=>({p,a:admission(r,p)})),accompanied=checks.filter(x=>x.a.needsCompanion&&x.a.status!=='blocked'),pending=checks.filter(x=>x.a.priceNeedsHeight),unknown=checks.filter(x=>x.a.status==='unknown'&&!x.a.needsCompanion);
  return `${accompanied.length?`<div class="companion-badge"><span aria-hidden="true">18+</span><strong>Только со взрослым 18+</strong></div>${people.length>1?`<p class="admission-note">Для ${accompanied.map(x=>esc(x.p.label)).join(', ')}. Уточните условия и оплату сопровождения на кассе перед покупкой.</p>`:'<p class="admission-note">Уточните условия и оплату сопровождения на кассе перед покупкой.</p>'}`:''}${pending.length?`<p class="admission-note">${pending.map(x=>esc(x.p.label)).join(', ')}: уточните рост, чтобы понять, нужен ли взрослый.</p>`:''}${!accompanied.length&&!pending.length&&unknown.length?'<p class="admission-note">Часть условий ещё нужно уточнить. Подробности ниже.</p>':''}`;
}
function isRequiredLine(line){if(line.autoCompanion)return true;if(!line.personId||person(line.personId)?.role!=='adult')return false;const draft=clone(state);draft.cart.lines=draft.cart.lines.filter(l=>l.id!==line.id);return VP3.reconcileCompanions(draft,purchaseOptions).additions.some(l=>l.personId===line.personId&&l.productId===line.productId&&l.rideId===line.rideId);}
function purchasePeople(){const pass=activeProduct==='unlimited';return `<div class="purchase-people" id="purchase-people"><div class="recipient-head"><h3>${pass?'Кому нужен безлимит?':'Для кого выбираем билеты?'}</h3><p class="helper">${pass?'Личное право на день. Уточните условия и оплату сопровождения на кассе перед покупкой.':'Один выбор для следующих билетов. Уточните условия и оплату сопровождения на кассе перед покупкой.'}</p></div>${state.party.length?`<div class="chips recipient-choices" role="group" aria-label="${pass?'Получатели безлимитов':'Получатель билетов'}">${state.party.map(p=>{const chosen=state.cart.lines.find(l=>l.productId==='unlimited'&&l.personId===p.id),auto=chosen&&isRequiredLine(chosen);return btn(pass?'direct-pass':'ticket-person',`${esc(p.label)} · ${esc(ageLabel(p))}${pass?'<span class="recipient-product-state">'+(auto?'Включён для сопровождения':chosen?'✓ В заказе':'Добавить')+'</span>':''}`,`data-person="${p.id}" aria-pressed="${pass?Boolean(chosen):ticketPersonId===p.id}" ${auto?'disabled':''}`,'chip');}).join('')}</div>`:''}<div class="btn-row">${btn('purchase-add-adult','+ Взрослый 18+',state.party.length>=8?'disabled':'','btn btn-outline')}${btn('purchase-add-child','+ Ребёнок',state.party.length>=8?'disabled':'','btn btn-outline')}</div>${person(ticketPersonId)?.role==='child'?`<div class="purchase-child-age">${agePicker(person(ticketPersonId))}</div>`:''}</div>`;}
function contextFixes(issues=[]){
  const rows=issues.filter(i=>i.code==='child-age-required'||i.code==='height-required'),seen=new Set();
  return rows.map(i=>{const p=person(i.personId);if(!p)return '';const key=i.code+':'+p.id;if(seen.has(key))return '';seen.add(key);return i.code==='child-age-required'&&!quick&&!reviewing&&p.id===ticketPersonId&&activeProduct!=='package'?`<p class="context-fix"><a class="btn btn-outline" href="#age-${p.id}">Выбрать возраст: ${esc(p.label)}</a></p>`:i.code==='child-age-required'?`<div class="context-fix"><strong>${esc(p.label)}: выберите возраст</strong>${agePicker(p)}</div>`:`<div class="context-fix"><label for="purchase-height-${p.id}"><strong>${esc(p.label)}: какой рост?</strong></label><p class="helper">От этого зависит, нужен ли оплаченный билет взрослому.</p><div class="height-input"><input id="purchase-height-${p.id}" data-field="height" data-person="${p.id}" data-ride="${esc(i.rideId||'demo-calm')}" inputmode="decimal" value="${p.height??''}" placeholder="Рост в см" aria-describedby="height-error-purchase-${p.id}"><span>см</span></div><span id="height-error-purchase-${p.id}" class="field-error" role="status"></span></div>`;}).join('');
}
function companionControls(extraIssues=[]){
  if(new URLSearchParams(location.search).get('review')!=='1')return '<p class="helper">Уточните условия и оплату сопровождения на кассе перед покупкой.</p>';
  const issues=[...(accompaniment?.issues||[]),...extraIssues],needed=state.cart.lines.some(l=>l.autoCompanion)||issues.some(i=>i.code.startsWith('companion-'))||Boolean(accompaniment?.requiredAdultId),adults=state.party.filter(p=>p.role==='adult'&&(p.age===null||p.age>=18)),chosen=person(state.companionId),fixes=contextFixes(issues);
  if(!needed&&!fixes)return '';
  if(needed&&chosen&&!fixes&&!issues.length&&!editingCompanion)return `<section class="companion-controls companion-summary" id="companion-controls"><p><strong>Сопровождает: ${esc(chosen.label)} · 18+</strong></p>${adults.length>1?btn('edit-companion','Изменить','','btn btn-text'):''}</section>`;
  const companionPrices=pricedCart(state).companionOptions||[];
  return `<section class="companion-controls" id="companion-controls" aria-labelledby="companion-heading">${needed?`${chosen&&adults.length===1?`<p id="companion-heading"><strong>Сопровождающий: ${esc(chosen.label)} · 18+</strong></p>`:`<h3 id="companion-heading">Кто сопровождает детей?</h3>`}${state.party.filter(p=>p.role==='child').length>1?'<p class="helper">Один взрослый, дети катаются с ним по очереди.</p>':''}${adults.length>1?`<div class="chips" role="group" aria-label="Сопровождающий взрослый">${adults.map(p=>btn('choose-companion',esc(p.label)+' · 18+'+(companionPrices.length>1&&new Set(companionPrices.map(x=>x.total)).size>1?' · '+money(companionPrices.find(x=>x.personId===p.id)?.total):''),`data-person="${p.id}" aria-pressed="${state.companionId===p.id}"`,'chip')).join('')}</div>`:''}${!adults.length?btn('purchase-add-companion','Добавить взрослого 18+',state.party.length>=8?'disabled':'','btn btn-outline'):''}${issues.filter(i=>i.code==='companion-unavailable').map(i=>note(i.message,'error')).join('')}`:''}${fixes}</section>`;
}
function agePicker(p){if(p.role==='adult')return '';const open=agePerson===p.id;return `<div class="child-age">${btn('edit-age',`<span>${p.age===null?'Выбрать возраст':esc(ageLabel(p))}</span><span>${open?'Свернуть':'Изменить'}</span>`,`id="age-${p.id}" data-person="${p.id}" aria-expanded="${open}" aria-controls="age-panel-${p.id}"`,'age-summary')}${open?`<div class="age-panel" id="age-panel-${p.id}" role="group" aria-label="Возраст: ${esc(p.label)}"><div class="age-grid">${Array.from({length:18},(_,n)=>btn('choose-age',n===0?'До года':String(n),`data-person="${p.id}" data-value="${n}" aria-label="${n===0?'До года':n+' лет'}" aria-pressed="${p.age===n}"`,'age-choice')).join('')}${btn('choose-age','Не знаю',`data-person="${p.id}" data-value="unknown" aria-pressed="${p.age===null}"`,'age-choice age-unknown')}</div></div>`:''}</div>`;}
function family(){return `<details class="family-panel" id="family" ${familyOpen?'open':''}><summary><span>${state.party.length?esc(state.party.map(personLabel).join(' / ')):'Кто идёт в парк?'}</span><span class="family-edit">${state.party.length?'Изменить':'Добавить семью'}</span></summary><p class="family-intro">Добавьте взрослых и детей. Детям выберите возраст, если знаете.</p><div class="party">${state.party.map((p,i)=>`<article class="person" id="person-${p.id}"><div class="person-head"><span class="avatar" aria-hidden="true">${i+1}</span><h3>${esc(p.label)}</h3>${p.role==='adult'?'<span class="adult-age"><strong>18+</strong></span>':''}${btn('remove-person','×',`data-person="${p.id}" aria-label="Убрать ${esc(p.label)}"`,'btn btn-text remove-person')}</div>${agePicker(p)}</article>`).join('')}</div><div class="btn-row">${btn('add-adult','+ Взрослый',state.party.length>=8?'disabled':'')}${btn('add-child','+ Ребёнок',state.party.length>=8?'disabled':'')}${btn('collapse-family',state.party.length?'Готово':'Смотреть все','','btn btn-dark')}</div></details>`;}
function catalogModes(){return `<div class="chips catalog-modes" role="group" aria-label="Каталог аттракционов">${btn('mode','Аттракционы парка',`data-mode="real" aria-pressed="${state.mode==='real'}"`,'chip')}${btn('mode','Учебный подбор',`data-mode="demo" aria-pressed="${state.mode==='demo'}"`,'chip')}</div>`;}
function demoTools(){return `<details class="demo-tools" id="demo-tools"><summary>О прототипе и данных</summary><p>Фотографии в блоках знакомства с парком настоящие. Учебные карточки используют фотографии парка и сгенерированные иллюстрации с отдельными подписями. Цены и правила служат вымышленными примерами. Образцы не действуют для посещения.</p>${document.body.dataset.page==='picker'?'':catalogModes()}<p class="helper">У настоящих аттракционов не подтверждены возрастные ориентиры, категории и ростовые ограничения. Они доступны для просмотра и сохранения.</p><div class="btn-row">${btn('sample','Пример: двое взрослых и дети 6 и 11 лет','','btn btn-text')}${btn('reset-state','Очистить мой выбор','','btn btn-text')}</div>${undo?.kind==='sample'?undoBanner():''}</details>`;}
function hero(kind){const picker=kind==='picker';return `<section class="hero v3-hero"><div class="hero-copy"><p class="eyebrow">${picker?'Ваш день в Victory Park':'Меньше считать. Больше кататься.'}</p><h1>${picker?'Всем найдётся<br><span>своё приключение</span>':'Билеты для<br><span>вашей семьи</span>'}</h1><p>${picker?'Укажите возраст, посмотрите развлечения и сохраните то, что хочется попробовать.':'Выберите, кто катается, и сравните готовые варианты. Или соберите свой заказ.'}</p>${!picker?'<a class="btn btn-text" href="attractions.html#plan">← К нашим аттракционам</a>':''}</div><figure class="hero-photo"><img src="assets/${picker?'wheel-of-happiness':'autodrom'}.webp" width="700" height="440" fetchpriority="high" alt="${picker?'Колесо счастья':'Автодром'} Victory Park"><figcaption>Настоящее фото парка</figcaption></figure></section>`;}
function displayedRides(){const list=rides();if(state.mode==='real'||focusPerson==='all'||!state.party.length)return list;const people=audience();if(!people.length)return list;return list.filter(r=>people.some(p=>admission(r,p).status!=='blocked'));}
function ageText(r){if(!r.fictional)return 'Правила допуска пока уточняются';const people=audience();if(!people.length)return 'Выберите возраст ребёнка, чтобы увидеть условия';const solo=people.filter(p=>admission(r,p).status==='solo');if(solo.length)return solo.map(p=>p.label).join(', ')+': самостоятельно по учебным правилам';if(people.every(p=>admission(r,p).status==='blocked'))return 'Пока не подходит выбранным участникам';const possible=people.filter(p=>admission(r,p).status!=='blocked');return possible.length?'По возрасту: '+possible.map(p=>p.label).join(', ')+'. Рост нужно проверить.':'Учебные условия допуска';}
function details(r){return `<details class="ride-details" id="details-${r.id}"><summary>Условия и рост</summary><p>${r.rules?`Учебные ограничения: рост от ${r.rules.min} до ${r.rules.max} см.${r.rules.soloMin>r.rules.min?' В части возрастов и при небольшом росте нужен взрослый.':''}`:'У парка нужно уточнить ограничения по возрасту, росту и сопровождению.'}</p>${r.fictional&&state.party.length?state.party.map(p=>`<p><strong>${esc(p.label)}:</strong> ${esc((admission(r,p).reasons||[]).join(' ')||'Уточните условия перед катанием.')}</p>`).join(''):''}<p class="helper">Учебные правила не являются правилами парка. Покупка не подтверждает допуск. Работу аттракциона проверяют в день посещения. <a href="availability.html">Посмотреть учебные статусы</a>.</p>${r.rules&&state.party.length?`<details class="height-detail" id="height-${r.id}"><summary>Уточнить известный рост</summary>${state.party.map(p=>`<div class="height-row"><label for="height-${r.id}-${p.id}">${esc(p.label)}</label><div class="height-input"><input id="height-${r.id}-${p.id}" data-field="height" data-person="${p.id}" data-ride="${r.id}" type="text" inputmode="decimal" value="${p.height??''}" placeholder="Не знаю" aria-describedby="height-error-${r.id}-${p.id}"><span>см</span></div><span class="field-error" id="height-error-${r.id}-${p.id}" role="status"></span><p class="helper">${p.height===null?'Можно оставить неизвестным.':esc((admission(r,p).reasons||[]).join(' '))}</p></div>`).join('')}</details>`:''}</details>`;}
function photoLabel(r){return r.photo?.startsWith('assets/demo-')?'Учебный пример · сгенерированное изображение':'Учебные условия · фото парка';}
function photoAttrs(r,kind='card'){if(!r.fictional||!r.photo||!r.photo.startsWith('assets/demo-'))return `src="${esc(r.photo)}"`;const stem=r.photo.replace(/\.webp$/,'');const sizes=kind==='plan'?'60px':kind==='product'?'(max-width:599px) 88px, 104px':'(max-width:359px) calc(100vw - 24px), (max-width:599px) calc(100vw - 32px), (max-width:999px) calc(50vw - 34px), (max-width:1279px) calc(50vw - 225px), (max-width:1359px) calc(50vw - 240px), 440px';return `src="${esc(r.photo)}" srcset="${esc(stem)}-thumb.webp 160w, ${esc(stem)}-small.webp 400w, ${esc(r.photo)} 720w" sizes="${sizes}"`;}
function rideCard(r,i){const chosen=selected().includes(r.id);return `<article class="ride-card ${chosen?'is-selected':''}" id="ride-${r.id}">${r.photo?`<figure class="ride-visual"><div class="ride-image"><img ${photoAttrs(r)} width="560" height="350" ${i===0?'loading="eager" fetchpriority="high"':'loading="lazy"'} alt="${esc(r.fictional?'Учебный пример: '+r.name:r.name+' в Victory Park')}"></div>${r.fictional?'<figcaption class="generated-label">'+photoLabel(r)+'</figcaption>':''}</figure>`:`<div class="demo-art" data-art="${['wave','speed','orbit','tower'][i%4]}" aria-hidden="true"><span>Учебный аттракцион</span></div>`}<div class="ride-body"><h3>${esc(r.name)}</h3>${r.fictional?'':`<div class="catalog-availability" data-availability-catalog-id="${esc(r.id)}"><a class="catalog-status unknown" href="availability.html">Уточняем</a><p class="catalog-status-detail">Проверяем учебный статус.</p></div>`}<p class="age-hint">${esc(ageText(r))}</p>${admissionMarkup(r)}<div class="ride-actions">${btn('toggle-ride',chosen?'✓ В нашем списке':'В наш список',`data-ride="${r.id}" aria-pressed="${chosen}"`,'btn '+(chosen?'btn-outline':'btn-primary'))}</div>${details(r)}</div></article>`;}
function undoBanner(){return undo?`<div class="undo-banner" role="status">${esc(undo.message)} ${btn('undo','Отменить','','btn btn-text')}</div>`:'';}
function plan(){return `<aside class="plan-panel" id="plan"><h2>Наш список <span class="plan-count">${selected().length}</span></h2><p>То, что хочется попробовать. Можно решить на месте.</p>${undo&&['ride','person','reset'].includes(undo.kind)?undoBanner():''}<div class="plan-items">${selected().map(rid=>{const r=ride(rid);return `<article class="plan-item compact-plan-item">${r.photo?`<img ${photoAttrs(r,'plan')} alt="${esc(r.fictional?'Учебный пример: '+r.name:r.name+' в Victory Park')}" width="60" height="50" loading="lazy">`:'<span class="plan-symbol" aria-hidden="true">'+esc(r.symbol||'○')+'</span>'}<div><h3>${esc(r.name)}</h3><p>${r.fictional&&audience().some(p=>admission(r,p).needsCompanion&&admission(r,p).status!=='blocked')?'Только со взрослым 18+':r.rules?'Учебные условия допуска':'Условия уточняются у парка'}</p><a href="#details-${r.id}" data-open-details="${r.id}">Условия</a></div>${btn('toggle-ride','×',`data-ride="${rid}" aria-label="Убрать ${esc(r.name)} из списка"`,'btn btn-text')}</article>`;}).join('')||'<p class="empty-list">Сохраняйте понравившееся одним нажатием.</p>'}</div><a class="btn btn-primary" href="tickets.html">Выбрать билеты →</a>${state.mode==='real'?'<p class="helper">Для настоящих аттракционов продажа пока не подключена.</p>':''}</aside>`;}
function renderPicker(){let cardIndex=0;const list=displayedRides(),groups=[['calm','Спокойные впечатления'],['exciting','Острые ощущения'],['other',state.mode==='real'?'Аттракционы парка':'Ещё впечатления']];return `${hero('picker')}${family()}<div class="section-head" id="catalog"><div><h2>${state.mode==='demo'?'Что попробуем?':'Аттракционы парка'}</h2><p>${state.mode==='demo'?'Показываем учебные аттракционы по возрасту. Сопровождение видно сразу, рост можно уточнить в условиях.':'Настоящие названия и фотографии. Категории и правила пока не подтверждены.'}</p></div></div>${catalogModes()}${state.mode==='real'?'<p class="catalog-status-note">Статусы учебные и меняются вместе со страницей <a href="availability.html">«Что сейчас работает»</a>. Работает: оценка по списаниям или отметка дежурного.</p>':'<p class="catalog-status-note">Фотографии парка и статусы работы доступны во вкладке «Аттракционы парка».</p>'}${state.party.length?`<div class="chips family-filter" aria-label="Показать аттракционы">${btn('focus-person','Для нашей семьи',`data-person="family" aria-pressed="${focusPerson==='family'}"`,'chip')}${btn('focus-person','Все',`data-person="all" aria-pressed="${focusPerson==='all'}"`,'chip')}<details class="person-filter" id="person-filter"><summary>Для одного</summary><div class="chips">${state.party.map(p=>btn('focus-person',esc(p.label),`data-person="${p.id}" aria-pressed="${focusPerson===p.id}"`,'chip')).join('')}</div></details></div>`:''}<div class="content-layout"><div class="catalog-groups">${!list.length?'<div class="empty"><h3>По этим условиям вариантов нет</h3><p>Можно посмотреть весь каталог или выбрать другого участника.</p>'+btn('focus-person','Посмотреть все','data-person="all"','btn btn-outline')+'</div>':''}${groups.map(([key,title])=>{const group=list.filter(r=>(r.intensity||'other')===key);return group.length?`<section class="catalog-group"><h3 class="group-title">${title}<span>${group.length}</span></h3><div class="catalog-grid">${group.map(r=>rideCard(r,cardIndex++)).join('')}</div></section>`:'';}).join('')}</div>${plan()}</div>${demoTools()}`;}
function riderPicker(){
 if(!state.party.length)return '';
 return `<section class="rider-section" id="riders"><h2>Кто будет кататься?</h2><p>Выберите катающихся. Варианты и полная цена появятся ниже.</p><div class="rider-choices">${state.party.map((p,i)=>btn('rider',`<span class="avatar" aria-hidden="true">${i+1}</span><span>${esc(p.label)}<small>${esc(ageLabel(p))}</small></span><span class="rider-check" aria-hidden="true">${state.riders.includes(p.id)?'✓':'○'}</span>`,`data-person="${p.id}" aria-pressed="${state.riders.includes(p.id)}"`,'rider-choice')).join('')}</div><a class="btn btn-text" href="attractions.html#family">Изменить семью</a></section>`;
}

function offerAmount(o){return o.conditional?(o.maxTotal>o.minTotal?money(o.minTotal)+' - '+money(o.maxTotal):'От '+money(o.total)):money(o.total);}
function offerMarkup(raw){
 const draft=clone(state);draft.cart.lines=raw.lines;const quoted=pricedCart(draft),current=pricedCart(state);const o={...raw,...quoted,notes:raw.notes,addedTotal:raw.alreadyAdded?0:!quoted.conditional&&!current.conditional?quoted.total-current.total:null};
 const single=o.mode==='add',r=single?ride(o.includedRideIds[0]):null,inc=o.includedRideIds.map(rid=>ride(rid)?.name).filter(Boolean),exc=(o.excludedRideIds||[]).map(rid=>ride(rid)?.name).filter(Boolean),hasCart=state.cart.lines.length>0;
 const people=(o.items||[]).map(item=>`${esc(item.label)}${item.needsCompanion?' со взрослым':''}`).join(' · ');
 const title=single?r.name:o.title;
 return `<article class="offer ${single?'single-offer':''}" id="offer-card-${o.id.replace(':','-')}">${single?`<div class="single-offer-heading"><img ${photoAttrs(r,'product')} width="88" height="88" loading="lazy" alt="${esc(r.name)}"><div><span class="badge" data-tone="demo">Одно катание</span><h3>${esc(title)}</h3></div></div>`:`<span class="badge" data-tone="${VP3.isPackage(o.productId)?'success':'demo'}">${VP3.isPackage(o.productId)?'Общий пакет':'Личный для каждого'}</span><h3>${esc(title)}</h3>`}
 <p class="offer-people">${single?people:esc(o.description)}</p>
 ${single&&o.items?.some(i=>i.needsCompanion)?'<p class="offer-companion">Взрослое катание включено в сумму.</p>':''}
 ${!o.unavailable?`<div class="offer-price">${offerAmount(o)}<small>${hasCart&&single?'Весь заказ после добавления':o.conditional?'Сумма зависит от уточнений':'Полная учебная цена с сопровождением'}${o.beforePromotion?' · до применения акции':promotion.offerId?' · с выбранной акцией':''}</small></div>`:''}
 ${hasCart&&single?`<p class="helper">${o.alreadyAdded?'Эти билеты уже в заказе.':o.conditional?'Текущие билеты сохранятся.':'Добавится на '+money(o.addedTotal)+'. Текущие билеты сохранятся.'}</p>`:''}
 ${!single?`<div class="offer-rights">${o.lines.map(l=>`<p><strong>${esc(l.productId==='unlimited'?person(l.personId)?.label||'Получатель':VP3.products[l.productId].name)}</strong> · ${l.productId==='unlimited'?'1 безлимит':l.quantity+' пакет'}${l.autoCompanion?' · сопровождающий':''}</p>`).join('')}${o.needsCompanionChoice?'<p><strong>+ 1 взрослый сопровождающий</strong><br>Выберете в заказе. Дети катаются с ним по очереди.</p>':''}</div><p class="helper">${VP3.isPackage(o.productId)?VP3.packageCapacity({lines:o.lines})+' билетов на компанию. Ребёнок и взрослый расходуют по билету.':'Повторы только на включённых аттракционах. Право нельзя передать другому.'}</p>`:''}
 ${o.excludedPeople?.length?`<p class="offer-exclusions">Не добавляем: ${o.excludedPeople.map(x=>esc(x.label)+': '+esc(x.reasons.join(' '))).join(' ')}</p>`:''}
 ${!single&&exc.length?`<p class="offer-exclusions">Из вашего списка не входит: ${exc.map(esc).join(', ')}.</p>`:''}
 ${!single?(o.notes||[]).filter(t=>t.startsWith('По указанному росту недоступно:')).map(t=>'<p class="offer-exclusions">'+esc(t)+'</p>').join(''):''}
 ${o.conditional?'<p class="offer-exclusions">'+[...new Set((o.issues||[]).map(i=>esc(i.message)))].join(' ')+'</p>':''}
 <details id="offer-${o.id}-terms"><summary>Условия и допуск</summary><p>${single?'Одно право для каждого указанного участника.':'Входят: '+inc.map(esc).join(' · ')+'.'}</p><p>Покупка не подтверждает допуск. ${single?'Рост и остальные ограничения проверяют перед катанием.':VP3.products[VP3.isPackage(o.productId)?(o.lines.find(VP3.isPackage)?.productId||'package5'):'unlimited'].terms.map(esc).join(' ')}</p></details>
 ${hasCart&&!single?'<p class="replacement-notice">Заменит текущий заказ этим составом. Замену можно отменить.</p>':''}
 ${btn('choose-offer',o.alreadyAdded?'✓ В заказе':o.unavailable?'Нет подходящих участников':hasCart&&!single?'Заменить заказ':single?'Добавить в заказ':o.conditional?'Выбрать и уточнить':'Выбрать за '+money(o.total),`data-offer="${o.id}" ${o.alreadyAdded||o.unavailable?'disabled':''}`,'btn btn-primary')}</article>`;
}
function recommendations(){
 if(!state.riders.length)return '';
 const rec=VP3.recommend({...state,ridersConfirmed:state.riders.length>0}),singles=rec.offers.filter(o=>o.mode==='add'),rest=rec.offers.filter(o=>o.mode!=='add');
 return `<section id="recommendations"><div class="section-head"><div><h2>${singles.length?'Катания из вашего списка':'Готовые варианты'}</h2><p>${singles.length?'Добавьте нужные. Весь список покупать необязательно.':'Сравните состав и полную цену.'}</p></div></div>${singles.length?'<div class="offers single-offers">'+singles.map(offerMarkup).join('')+'</div>':''}${rest.length?`<h3 class="more-offers-title">${singles.length?'Пакеты и безлимиты':'Для вашей семьи'}</h3><div class="offers">${rest.map(offerMarkup).join('')}</div>`:''}${!rec.offers.length?'<p>Подходящего готового варианта нет. Выберите билеты ниже.</p>':''}${(rec.warnings||[]).filter(t=>t.startsWith('Безлимит не предложен:')).map(t=>'<p class="offer-exclusions">'+esc(t)+'</p>').join('')}${(rec.errors||[]).map(t=>note(typeof t==='string'?t:t.message,'error')).join('')}</section>`;
}
function currentQty(target){return state.cart.lines.filter(l=>!l.autoCompanion&&(target.startsWith('ticket:')?l.productId==='ticket'&&l.rideId===target.slice(7)&&l.personId===ticketPersonId:target.startsWith('line:')?l.id===target.slice(5):false)).reduce((sum,l)=>sum+l.quantity,0);}
function quantity(target,n){return `<div class="quantity-choice"><span class="quantity-label">${target==='quick:unlimited'?(state.cart.lines.some(l=>l.productId==='unlimited'&&l.personId)?'Ещё для скольких человек?':'Сколько человек?'):'Количество билетов'}</span><div class="quantity-pills" role="group" aria-label="Количество товара">${[1,2,3,4].map(q=>btn('quantity',q,`data-target="${esc(target)}" data-value="${q}" aria-pressed="${n===q}"`,'quantity-pill')).join('')}${btn('custom-quantity',n>4?String(n):'Другое',`data-target="${esc(target)}" aria-pressed="${n>4}"`,'quantity-pill')}</div>${customTarget===target?`<form class="custom-quantity-form" data-target="${esc(target)}"><label for="custom-quantity">От 1 до 20</label><div class="btn-row"><input id="custom-quantity" name="quantity" type="text" inputmode="numeric" value="${n||''}" aria-describedby="quantity-error" autocomplete="off"><button type="submit" class="btn btn-dark">Применить</button></div><span id="quantity-error" class="field-error" role="alert"></span></form>`:''}</div>`;}
function directProducts(){const recipient=person(ticketPersonId);return `<section class="direct-products" id="direct"><div class="section-head"><div><h2>${directEntry?'Безлимиты, пакеты и билеты':'Выбрать самому'}</h2><p>Учебная покупка · деньги не списываются.${returnMode==='real'&&state.selections.real.length?' Настоящие аттракционы сохранены в вашем списке отдельно.':''}</p></div></div><div class="product-tabs chips" aria-label="Вид продукта">${[['unlimited','Безлимиты'],['package','Пакеты'],['single','Билеты']].map(([value,label])=>btn('product-focus',label,`data-product="${value}" aria-pressed="${activeProduct===value}"`,'chip')).join('')}</div>${activeProduct==='single'?`${purchasePeople()}${VP3.demoRides.slice().sort((a,b)=>Number(b.id===deepRide?.id)-Number(a.id===deepRide?.id)||Number(state.selections.demo.includes(b.id))-Number(state.selections.demo.includes(a.id))).map(r=>{const a=recipient?admission(r,recipient):null;return `<article class="product" id="product-${r.id}" tabindex="-1"><div class="product-intro">${r.photo?`<img ${photoAttrs(r,'product')} width="104" height="104" loading="lazy" alt="Учебный пример: ${esc(r.name)}">`:''}<div><h3>${esc(r.name)}</h3>${state.selections.demo.includes(r.id)?'<p class="helper">В вашем списке</p>':''}<div class="offer-price">${money(r.price)}<small>Одно право катания</small></div></div></div>${r.photo?'<p class="generated-label">'+photoLabel(r)+'</p>':''}${new URLSearchParams(location.search).get('review')==='1'&&a?.needsCompanion&&a.status!=='blocked'?`<div class="companion-badge"><span aria-hidden="true">18+</span><strong>Только со взрослым 18+</strong></div><p class="helper">Ребёнок + взрослый: ${money(r.price+(VP3.admissionRules?.[r.id]?.adultPrice??r.price))} за одно совместное катание. Уже выбранное право взрослого учтём.</p>`:'<p class="helper">Один билет на одно катание. Покупка не подтверждает допуск.</p>'}${a?.priceNeedsHeight?'<p class="helper">Рост уточним в заказе: от него зависит билет взрослого.</p>':''}${a?.status==='blocked'?`<p class="offer-exclusions">${esc(recipient.label)}: ${esc((a.reasons||[]).join(' '))}</p>`:recipient?quantity('ticket:'+r.id,currentQty('ticket:'+r.id)):'<a class="btn btn-outline" href="#purchase-people">Выбрать получателя выше</a>'}</article>`;}).join('')}`:activeProduct==='package'?packageProduct():`<article class="product" id="product-unlimited" tabindex="-1"><span class="badge" data-tone="demo">Личный на день первого использования</span><h3>Безлимит</h3><div class="offer-price">${money(VP3.products.unlimited.price)}<small>Для одного человека</small></div><p>Повторы без ограничения: ${VP3.products.unlimited.includedRideIds.map(rid=>esc(ride(rid).name)).join(', ')}.</p><p class="helper">${esc(ride('demo-small').name)} и ${esc(ride('demo-unknown').name)} не входят. Передать другому нельзя.</p>${new URLSearchParams(location.search).get('review')==='1'?'<p class="helper" data-review-only>Если ребёнку нужен взрослый, в заказ войдёт и его безлимит. Один взрослый сопровождает детей по очереди.</p>':''}${purchasePeople()}</article>`}</section>`;}
function checkoutSwitch(){
 const query=new URLSearchParams(location.search);query.set('product',activeProduct);query.delete('resume');
 return `<nav class="checkout-switch" aria-label="Вариант покупки"><a data-checkout-switch href="quick.html?${esc(query.toString())}" ${quick?'aria-current="page"':''}>Быстрая покупка</a><a data-checkout-switch href="tickets.html?${esc(query.toString())}" ${quick?'':'aria-current="page"'}>С подбором</a></nav>`;
}
function packageChoices(){
 const lines=state.cart.lines.filter(l=>VP3.isPackage(l)),selectedId=lines.length===1&&lines[0].quantity===1?lines[0].productId:'';
 return `<div class="package-choice"><p class="package-label">Билетов в пакете</p><div class="package-grid" role="group" aria-label="Размер пакета">${VP3.packageProducts.map(p=>btn('package-size',`<strong>${p.rides}</strong><span>${new Intl.NumberFormat('ru-RU').format(p.price)} ֏</span>`,`data-product="${p.id}" aria-pressed="${selectedId===p.id}" aria-label="${p.rides} билетов за ${money(p.price)}"`,'package-size')).join('')}</div>${lines.length>1||lines.some(l=>l.quantity>1)?'<p class="helper">Выбор размера заменит все пакеты в заказе одним новым пакетом. Остальные билеты сохранятся.</p>':''}</div>`;
}
function packageProduct(){return `<article class="product" id="product-package" tabindex="-1"><h3>Пакет для всей компании</h3>${packageChoices()}<p class="package-terms"><strong>Любые аттракционы · 30 дней с покупки.</strong><br>1 билет = 1 катание 1 человека. Можно делить и приходить в разные дни.</p><p class="helper">Уточните условия и оплату сопровождения на кассе перед покупкой.</p></article>`;}
function quickCurrentQty(){
 return state.cart.lines.filter(l=>activeProduct==='unlimited'?l.productId==='unlimited'&&VP3.isDirectLine(l):l.productId==='ticket'&&l.rideId===quickRideId&&(quickPersonId?l.personId===quickPersonId:VP3.isDirectLine(l))).reduce((n,l)=>n+l.quantity,0);
}
function quickProduct(){
 if(activeProduct==='package')return packageProduct();
 if(activeProduct==='unlimited')return `<article class="quick-product" id="product-unlimited" tabindex="-1"><div class="quick-product-heading"><h2>${esc(VP3.products.unlimited.name)}</h2><strong>${money(VP3.products.unlimited.price)}<small>за человека</small></strong></div><p>В любой день после покупки. Действует в день первого использования.</p>${state.cart.lines.some(l=>l.productId==='unlimited'&&l.personId)?'<p class="quick-important">Именные безлимиты уже в заказе: '+state.cart.lines.filter(l=>l.productId==='unlimited'&&l.personId).length+'. Здесь добавляются безлимиты для других людей.</p>':''}${quantity('quick:unlimited',quickCurrentQty())}<p class="quick-important">Уточните условия и оплату сопровождения на кассе перед покупкой.</p><p class="quick-important">Входят: ${VP3.products.unlimited.includedRideIds.map(rid=>esc(ride(rid)?.name)).join(', ')}. Код обменивается в кассе на личный носитель.</p></article>`;
 const chosen=ride(quickRideId),recipient=person(quickPersonId);
 return `<article class="quick-product" id="product-single" tabindex="-1"><label class="quick-label" for="quick-ride">Аттракцион</label><select id="quick-ride" data-field="quick-ride">${VP3.demoRides.map(r=>`<option value="${r.id}" ${r.id===quickRideId?'selected':''}>${esc(r.name)} · ${money(r.price)}</option>`).join('')}</select>${!quickPersonId&&state.cart.lines.some(l=>l.productId==='ticket'&&l.rideId===quickRideId&&l.personId)?'<p class="quick-important">Билеты для выбранных участников уже сохранены в заказе. Здесь добавляются отдельные билеты.</p>':''}${quantity('quick:ticket',quickCurrentQty())}<p class="quick-important">1 билет = 1 катание 1 человека. Действует в день первого использования.</p><p class="quick-important">Уточните условия и оплату сопровождения на кассе перед покупкой.</p>${recipient?`<p class="quick-important">Получатель: <strong>${esc(recipient.label)}</strong>. Известные условия сопровождения учтены. Допуск проверят перед катанием.</p>`:''}<details class="quick-recipient" id="quick-recipient"><summary>${recipient?'Изменить получателя':'Указать получателя (необязательно)'}</summary><p>Для известного участника поможем учесть возраст, рост и сопровождение. Без выбора все участники получают отдельные права, допуск проверяется перед катанием.</p><label for="quick-person">Для кого следующие билеты</label><select id="quick-person" data-field="quick-person"><option value="">Уточню перед катанием</option>${state.party.map(p=>`<option value="${p.id}" ${p.id===quickPersonId?'selected':''}>${esc(personLabel(p))}</option>`).join('')}</select><a href="attractions.html#family">Изменить компанию</a></details>${chosen?`<details id="quick-ride-terms"><summary>Условия аттракциона</summary>${details(chosen)}</details>`:''}</article>`;
}
function quickCart(){
 const a=calculateCart(state,promotion),q=basketQuote(),lines=state.cart.lines;
 return `<section class="quick-order" id="cart" tabindex="-1"><div class="quick-order-heading"><h2>Ваш заказ</h2><span>${lines.length?money(q.payable):'Пока пусто'}</span></div>${lines.length?`${companySummary()}${companionControls()}${cartLines()}<p class="quick-important">${VPC.validitySummary(lines,promotion).map(esc).join(' ')}</p>${a.discount?`<div class="price-breakdown"><span>До скидки</span><strong>${money(a.subtotal)}</strong><span>Скидка</span><strong>−${money(a.discount)}</strong></div>`:''}${a.bonus?`<p>+${money(a.bonus)} на следующий визит, с ${a.bonusValidFrom} по ${a.bonusValidUntil}.</p>`:''}${a.excludedRideIds?.length?`<p class="offer-exclusions">Не входит из списка: ${a.excludedRideIds.map(rid=>esc(ride(rid)?.name)).join(', ')}.</p>`:''}${promotion.offerId?promotionControls(a):'<details class="optional-promotion" id="optional-promotion"><summary>Добавить акцию</summary>'+promotionControls(a)+'</details>'}${q.conditional?'<p class="helper">Уточните данные. До этого оплата недоступна.</p>':''}${a.issues.length?btn('remove-promotion','Продолжить без акции за '+money(calculateCart(state,VPC.normalizePromotion(null)).payable),'','btn btn-outline'):''}`:'<p>'+ (activeProduct==='unlimited'?'Выберите количество безлимитов.':activeProduct==='package'?'Выберите размер пакета.':'Выберите количество билетов.')+' Ничего не добавляется автоматически.</p>'}<div id="checkout-errors" role="alert">${formError?note(formError,'error'):''}${lines.length?a.errors.map(e=>note(typeof e==='string'?e:e.message,'error')).join(''):''}</div>${undo?.kind==='cart'?undoBanner():''}<p class="quick-important">Оплачиваете выбранные билеты. Возраст и рост проверят перед катанием. Уточните условия и оплату сопровождения на кассе перед покупкой.</p><p class="quick-important">После оплаты образцы сразу здесь. Почта необязательна. Деньги не списываются.</p>${lines.some(l=>l.productId==='unlimited')?'<p class="quick-important">Код безлимита обменивается в кассе на личный носитель.</p>':''}<div class="quick-desktop-action">${nextButton('btn btn-primary pay-button')}</div><details class="quick-terms" id="order-terms"><summary>Все условия покупки</summary><p>Учебные цены, ограничения и правила. Образцы не действуют для прохода. Возвраты и реальные продажи пока не подключены.</p><p>Уточните условия и оплату сопровождения на кассе перед покупкой. Покупка не подтверждает допуск. Пакет можно делить между людьми, безлимит персональный.</p>${a.warnings.map(e=>'<p>'+esc(typeof e==='string'?e:e.message)+'</p>').join('')}</details><details class="demo-scenarios"><summary>Другой исход демо-оплаты</summary><label for="scenario">Учебный ответ оплаты</label><select id="scenario" data-field="scenario">${[['success','Успех'],['declined','Отклонено'],['pending','Результат неизвестен'],['issuance','Оплачено, выдача задержана'],['partial','Оплачено, готова часть билетов'],['offline','Связь потеряна после начала']].map(([v,l])=>`<option value="${v}" ${v===scenario?'selected':''}>${l}</option>`).join('')}</select></details></section>`;
}
function renderQuick(){
 if(!order&&needsProductChoice)return `<div class="quick-flow"><h1 class="v5-format-heading">Выберите формат билетов</h1><p>Выберите подходящий вариант. Ничего не добавляется автоматически.</p><div class="v5-format-choices">${[['single','Билеты'],['package','Пакеты'],['unlimited','Безлимиты']].map(([value,label])=>btn('product-focus',label,`data-product="${value}" aria-pressed="false"`,'btn btn-outline')).join('')}</div>${purchases()}</div>`;
 if(order)return checkoutSwitch()+receipt();
 if(purchaseRouteIssue)return purchaseRouteNotice()+purchases();
 return `<div class="quick-flow">${checkoutSwitch()}<h1>Выберите билеты</h1><div class="quick-tabs" role="group" aria-label="Вид покупки">${[['unlimited','Безлимиты'],['package','Пакеты'],['single','Билеты']].map(([v,label])=>btn('product-focus',label,`data-product="${v}" aria-pressed="${activeProduct===v}"`,'quick-tab')).join('')}</div><div class="quick-layout"><section class="quick-choice" id="direct" tabindex="-1">${quickProduct()}</section>${quickCart()}</div><div class="quick-context">${purchases()}${state.party.length||state.selections.demo.length||state.selections.real.length?'<details id="quick-saved-context"><summary>Наша компания и выбранные аттракционы</summary>'+savedContext()+'</details>':''}<a class="quick-catalog-link" href="${pickerReturn()}">Посмотреть аттракционы</a></div></div>`;
}
function choosePackage(productId){
 if(!VP3.isPackage(productId))return;
 const p=VP3.products[productId],lines=state.cart.lines.filter(l=>!VP3.isPackage(l));
 lines.push({id:id(),productId,rideId:null,personId:null,recipientKey:null,quantity:1,unitPrice:p.price});
 customTarget='';commitCart(lines,`${p.rides} билетов в пакете. Итого ${money(lines.reduce((sum,l)=>sum+l.unitPrice*l.quantity,0))}.`,false);
}
function setQuickQuantity(target,n){
 if(!Number.isInteger(n)||n<1||n>20)return false;
 let lines=clone(state.cart.lines);
 if(target==='quick:unlimited'){
  const existing=lines.filter(l=>l.productId==='unlimited'&&VP3.isDirectLine(l));
  lines=lines.filter(l=>!(l.productId==='unlimited'&&VP3.isDirectLine(l)));
  for(let i=0;i<n;i++)lines.push(existing[i]||{id:id(),productId:'unlimited',rideId:null,personId:null,recipientKey:'direct-pass-'+id(),quantity:1,unitPrice:VP3.products.unlimited.price});
 }else{
  const chosen=ride(quickRideId);if(!chosen?.fictional)return false;
  const matching=lines.filter(l=>!l.autoCompanion&&l.productId==='ticket'&&l.rideId===quickRideId&&(quickPersonId?l.personId===quickPersonId:VP3.isDirectLine(l))),line=matching[0];
  if(line){line.quantity=n;lines=lines.filter(l=>!matching.includes(l)||l===line);}else lines.push({id:id(),productId:'ticket',rideId:quickRideId,personId:quickPersonId||null,recipientKey:quickPersonId?null:'direct-ticket-'+id(),quantity:n,unitPrice:chosen.price});
 }
 customTarget='';commitCart(lines,'Количество изменено. Полная сумма обновлена.',false);return true;
}
function lineName(l){return l.productId==='ticket'?'Билет: '+(ride(l.rideId)?.name||'Аттракцион'):VP3.products[l.productId]?.name||'Товар';}
function lineRecipient(l){return VP3.isPackage(l)?'Общий пакет для компании':person(l.personId)?.label||l.recipientLabel||(VP3.isDirectLine(l)?l.productId==='unlimited'?'Личный безлимит · получатель при обмене':'Для одного человека на каждое катание':'Выберите получателя');}
function savedContext(){
  const names=state.selections.demo.map(rid=>ride(rid)?.name).filter(Boolean);
  return `<div class="saved-context">${state.party.length?`<p>${state.party.map(p=>esc(personLabel(p))).join(' · ')} <a href="attractions.html#family">Изменить семью</a></p>`:''}${names.length?`<p>В вашем списке: ${names.map(esc).join(' · ')}. <a href="attractions.html?mode=demo#plan">Изменить аттракционы</a></p>`:''}${state.selections.real.length?`<p class="helper">Аттракционы парка сохранены отдельно: ${state.selections.real.map(rid=>esc(ride(rid)?.name)).join(' · ')}. Учебные билеты на них не действуют. <a href="attractions.html?mode=real#plan">К аттракционам парка</a></p>`:''}</div>`;
}
function promotionControls(a){
  const selectedOffer=VPO.getOffer(promotion.offerId), dates=a.issues.filter(i=>i.code.startsWith('visit-'));
  return `<section class="cart-promotion" id="cart-promotion" aria-labelledby="promotion-heading"><h3 id="promotion-heading">Акция в заказе</h3><label for="cart-offer">Одно предложение для этого заказа</label><select id="cart-offer" data-field="promotion"><option value="none" ${!promotion.offerId?'selected':''}>Без предложения</option>${VPO.offers.filter(o=>o.status==='active').map(o=>`<option value="${o.id}" ${promotion.offerId===o.id?'selected':''}>${esc(o.title)}</option>`).join('')}${promotion.offerId&&(!selectedOffer||selectedOffer.status!=='active')?`<option selected value="${esc(promotion.offerId)}">${esc(selectedOffer?.title||'Неизвестное предложение')}</option>`:''}</select><a class="btn btn-text" href="offers.html">Сравнить все предложения →</a>${selectedOffer?`<p>${esc(selectedOffer.benefit)}</p>${selectedOffer.id==='weekday20'?`<div class="promotion-date" id="promotion-date"><label for="cart-visit-date">Когда придёте?</label><div class="btn-row">${btn('promo-date','Сегодня',`data-date="${VPO.getToday()}" aria-pressed="${promotion.visitDate===VPO.getToday()}"`,'btn btn-outline')}${btn('promo-date','Завтра',`data-date="${nextDay(VPO.getToday())}" aria-pressed="${promotion.visitDate===nextDay(VPO.getToday())}"`,'btn btn-outline')}</div><input type="date" id="cart-visit-date" data-field="visit-date" value="${esc(promotion.visitDate||'')}" min="${VPO.getToday()}" max="2026-11-30" aria-describedby="cart-date-help"><p id="cart-date-help" class="helper">${dates.length?dates.map(i=>esc(i.message)).join(' '):'Скидка на отдельные билеты в выбранный будний день. Пакеты и безлимиты по обычной цене.'}</p></div>`:''}${selectedOffer.id==='student15'?`<label class="promotion-check" id="promotion-student"><input id="cart-student" type="checkbox" data-field="student" ${promotion.studentAcknowledged?'checked':''}><span>Все разовые билеты в этом заказе для одного владельца действующего студенческого. Он покажет документ при получении.</span></label>`:''}<details class="order-terms"><summary>Условия предложения</summary>${selectedOffer.terms.map(t=>'<p>'+esc(t)+'</p>').join('')}</details>`:''}${a.issues.filter(i=>!i.code.startsWith('visit-')).map(i=>note(i.message,'error')).join('')}${a.applied&&state.cart.lines.some(l=>l.productId!=='ticket')&&['weekday20','student15','bonus500'].includes(promotion.offerId)?'<p class="helper">Выгода рассчитана только для разовых билетов. Пакеты и безлимиты остаются в заказе по полной цене.</p>':''}</section>`;
}
function nextDay(value){const date=new Date(value+'T12:00:00Z');date.setUTCDate(date.getUTCDate()+1);return date.toISOString().slice(0,10);}
function promotionAction(a){
  if(a.issues.some(i=>i.code.startsWith('visit-')))return {label:'Выбрать дату',target:'cart-visit-date'};
  if(a.issues.some(i=>i.code==='student-acknowledgement-required'))return {label:'Подтвердить льготу',target:'cart-student'};
  if(a.issues.some(i=>i.code==='incompatible-product'||i.code==='bonus-threshold'))return {label:promotion.offerId==='package5'?'Добавить пакет':promotion.offerId==='unlimited'?'Выбрать получателя':'Добавить билеты',target:'direct'};
  return {label:'Проверить предложение',target:'cart-offer'};
}
function focusField(target){const el=document.getElementById(target);if(!el)return;let ancestor=el.parentElement;while(ancestor){if(ancestor.tagName==='DETAILS')ancestor.open=true;ancestor=ancestor.parentElement;}el.scrollIntoView({block:'center',behavior:'auto'});if(!el.matches('input,select,button,a'))el.setAttribute('tabindex','-1');el.focus({preventScroll:true});}
function orderTotals(o){return `${o.promotion?.offerId?`<p>${esc(VPO.getOffer(o.promotion.offerId)?.title||'Предложение')}${o.promotion.offerId==='weekday20'?' · '+esc(o.promotion.visitDate):''}</p>`:''}${o.discount?`<div class="price-breakdown"><span>Полная стоимость</span><strong>${money(o.subtotal)}</strong><span>Скидка</span><strong>−${money(o.discount)}</strong></div>`:''}${o.bonus&&o.status==='success'?`<p>Бонус на следующий визит: ${money(o.bonus)}. С ${esc(o.bonusValidFrom)} по ${esc(o.bonusValidUntil)}. Сейчас оплачивается полная цена.</p>`:''}`;}
function legacyRecipient(l){
 if(VP3.isPackage(l)||person(l.personId)||VP3.isDirectLine(l))return '';
 const product=l.productId==='unlimited'?'unlimited':'single',canContinue=quick&&!l.autoCompanion;
 return `<div class="line-recipient-fix"><p class="helper">${canContinue?'Можно продолжить без анкеты. Уточните условия и оплату сопровождения на кассе перед покупкой.':'Для старого черновика нужно выбрать получателя, чтобы учесть сопровождение.'}</p><div class="chips">${state.party.map(p=>btn('assign-line-person',esc(p.label)+' · '+esc(ageLabel(p)),`data-line="${l.id}" data-person="${p.id}"`,'chip')).join('')}</div>${canContinue?btn('make-direct-line','Продолжить без анкеты',`data-line="${l.id}"`,'btn btn-outline'):''}${!state.party.length?(quick?`<a class="btn btn-text" data-checkout-switch href="tickets.html?product=${product}#cart">Указать получателя</a>`:btn('fix-recipient','Добавить получателя',`data-product="${product}"`,'btn btn-outline')):''}</div>`;
}
function pricedCart(input){
 const q=VP3.quoteCart(input,purchaseOptions), options=q.needsCompanionChoice?q.companionOptions.filter(x=>x.available):[{personId:input.companionId,total:q.total}];
 let beforePromotion=false;
 const priced=options.map(option=>{const draft=clone(input);if(q.needsCompanionChoice){if(option.personId){draft.companionId=option.personId;}else{draft.party.push({id:'quote-adult',label:'Сопровождающий',role:'adult',age:18,height:null});draft.companionId='quote-adult';}draft.companionAutoSelected=false;}const result=calculateCart(draft,promotion);if(result.issues.length)beforePromotion=true;return {...option,total:result.issues.length?option.total:result.payable};});
 const totals=priced.map(x=>x.total),total=totals.length?Math.min(...totals):q.total,max=q.maxTotal===null?null:totals.length?Math.max(...totals):q.maxTotal;
 return {...q,total,payable:total,minTotal:total,maxTotal:max,beforePromotion,companionOptions:priced};
}
function basketQuote(){return pricedCart(state);}
function cartLines(){
 const groups=new Map();for(const l of state.cart.lines){const key=l.productId==='ticket'?'ticket:'+l.rideId:l.productId;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(l);}
 return [...groups.values()].map(lines=>`<article class="cart-group" data-product="${esc(lines[0].productId)}"><h3>${esc(lines[0].productId==='ticket'?ride(lines[0].rideId)?.name:VP3.products[lines[0].productId]?.name||'Неизвестный товар')}</h3>${lines.map(l=>`<div class="cart-person ${l.autoCompanion?'is-companion-line':''}"><div><strong>${esc(lineRecipient(l))}</strong>${l.autoCompanion?'<small>Сопровождающий 18+</small>':''}${VP3.isPackage(l)?`<small>${VP3.packageCapacity(l)} билетов</small>`:l.quantity>1?`<small>${l.quantity} прав</small>`:''}</div><strong>${money(l.unitPrice*l.quantity)}</strong></div>${legacyRecipient(l)}`).join('')}<details class="cart-edit" id="edit-${lines[0].id}"><summary>Изменить</summary>${lines.map(l=>`<div class="cart-edit-person"><strong>${esc(lineRecipient(l))}</strong>${!isRequiredLine(l)?btn('remove-line','Убрать',`data-line="${l.id}"`,'btn btn-text'):'<p class="helper">Это право нужно для сопровождения.</p>'}${VP3.isPackage(l)?packageChoices():!l.autoCompanion&&l.productId!=='unlimited'?quantity('line:'+l.id,l.quantity):''}</div>`).join('')}</details></article>`).join('');
}
function reviewToken(){return JSON.stringify([state.party,state.cart,state.companionId,promotion]);}
function needsReview(){
 const main=state.cart.lines.filter(l=>!l.autoCompanion);
 const people=new Set(main.map(l=>l.personId).filter(Boolean));
 const products=new Set(main.map(l=>l.productId+':'+(l.rideId||'')));
 return people.size>1||products.size>1||Boolean(calculateCart(state,promotion).excludedRideIds?.length);
}
function checkoutNext(){
 if(!state.cart.lines.length&&quick)return {action:'show-products',label:activeProduct==='package'?'Выберите размер':'Выберите количество',title:'Ваш заказ',small:'Оплата после выбора',disabled:true};
 if(!state.cart.lines.length){
  const target=directEntry?(activeProduct==='package'?'product-package':activeProduct==='unlimited'||!person(ticketPersonId)?'purchase-people':'product-'+(deepRide?.fictional?deepRide.id:state.selections.demo[0]||VP3.demoRides[0].id)):'';
  const label=!directEntry&&state.party.length&&!state.riders.length?'Выбрать катающихся':target==='product-package'?'Выбрать размер пакета':target==='purchase-people'?'Выбрать получателя':'Выбрать катание';
  return {action:'show-products',label,target,title:'Выберите покупку',small:'Оплата после выбора'};
 }
 const q=basketQuote(),title=q.conditional?`От ${money(q.minTotal??q.total)}`:money(q.payable);
 if(companyContext()?.changed)return {action:'recalculate-company',label:'Пересчитать состав',title,small:'Компания изменилась'};
 const first=accompaniment?.issues?.[0],a=calculateCart(state,promotion);
 if(first){const target=first.code==='height-required'?'purchase-height-'+first.personId:first.code==='child-age-required'?'age-'+first.personId:first.code.startsWith('companion-')?'companion-controls':'checkout-errors';return {action:'fix-order',label:first.code==='height-required'?'Уточнить рост':first.code==='child-age-required'?'Выбрать возраст':first.code.startsWith('companion-')?'Выбрать взрослого':'Уточнить заказ',target,title,small:'Перед оплатой'};}
 if(a.issues.length){const fix=promotionAction(a);return {action:'promo-fix',...fix,title,small:'Условия акции'};}
 if(!a.canCheckout)return {action:'fix-order',label:'Проверить данные',target:'checkout-errors',title,small:'Перед оплатой'};
 if(!quick&&needsReview()&&!reviewing)return {action:'review-order',label:'Проверить состав',title,small:'Несколько прав в заказе'};
 return {action:'pay',label:'Оплатить '+money(a.payable),title,small:'Демо · без списания',disabled:busy};
}

function nextButton(cls='btn btn-primary'){const n=checkoutNext();return btn(n.action,n.label,`data-checkout-next ${n.target?'data-target="'+n.target+'"':''} ${n.disabled?'disabled':''}`,cls);}
function checkoutBar(){const n=checkoutNext();return `<div class="mobile-bar checkout-dock"><div><strong>${n.title}</strong><small>${n.small}</small></div>${nextButton()}</div>`;}
function reviewOrder(){if(!state.cart.lines.length)return;reviewing=true;reviewedToken=reviewToken();render();window.scrollTo({top:0,behavior:'instant'});$('#review-heading')?.focus({preventScroll:true});}
function cartPreview(){return state.cart.lines.length?cart():`<section class="cart-preview" id="cart"><h2>Ваш заказ</h2><p>Выберите нужные катания. Лайки сами не становятся покупкой.</p></section>`;}

function cart(){
 const a=calculateCart(state,promotion),q=basketQuote();
 return `<section class="cart-panel review-cart" id="cart" tabindex="-1">${reviewing?'':'<h2>Ваш заказ</h2>'}${undo?.kind==='cart'?undoBanner():''}${companySummary()}${companionControls()}${cartLines()}${q.needsCompanionChoice?'<p class="helper">Сумма учитывает необходимого взрослого. Выберите, кто будет сопровождать.</p>':''}${promotion.offerId?promotionControls(a):'<details class="optional-promotion" id="optional-promotion"><summary>Добавить акцию</summary>'+promotionControls(a)+'</details>'}${a.discount?`<div class="price-breakdown"><span>Полная стоимость</span><strong>${money(a.subtotal)}</strong><span>Скидка</span><strong>−${money(a.discount)}</strong></div>`:''}<div class="total"><span>${q.conditional?'Пока от':'Итого'}</span><strong>${money(q.payable)}</strong></div>${q.conditional?'<p class="helper">Уточните данные. До этого оплата недоступна.</p>':''}${a.bonus?`<p class="helper">+${money(a.bonus)} на следующий визит, с ${a.bonusValidFrom} по ${a.bonusValidUntil}.</p>`:''}${a.excludedRideIds?.length?`<p class="offer-exclusions">Не входит из списка: ${a.excludedRideIds.map(rid=>esc(ride(rid)?.name)).join(', ')}.</p>`:''}<p class="review-validity">${VPC.validitySummary(state.cart.lines,promotion).map(esc).join(' ')} Допуск проверяют перед катанием.</p><p class="review-validity">Получение: образцы появятся здесь. ${state.cart.lines.some(l=>l.productId==='unlimited')?'Безлимит в учебной модели обменивается в демонстрационной кассе на личный носитель.':'Образцы не действуют для посещения.'}</p><p class="review-validity">Возврат: реальной оплаты нет. Условия парка пока не утверждены.</p><details class="order-terms" id="order-terms"><summary>Условия и ограничения</summary><p>${VPC.validitySummary(state.cart.lines,promotion).map(esc).join(' ')} Парк эти условия ещё не утвердил.</p><p>Пакет расходует по праву за каждого участника. Уточните условия и оплату сопровождения на кассе перед покупкой. Дети катаются с одним взрослым по очереди.</p>${a.warnings.map(e=>'<p>'+esc(typeof e==='string'?e:e.message)+'</p>').join('')}</details><div id="checkout-errors" role="alert">${formError?note(formError,'error'):''}${a.errors.map(e=>note(typeof e==='string'?e:e.message,'error')).join('')}</div>${a.issues.length?btn('remove-promotion','Продолжить без акции за '+money(calculateCart(state,VPC.normalizePromotion(null)).payable),'','btn btn-outline'):''}<p class="review-complete" id="review-end">После подтверждения выдачи билеты будут здесь. Контакт не нужен.<br>Учебная оплата, деньги не списываются.</p><div id="review-action">${nextButton('btn btn-primary pay-button')}</div><details class="demo-scenarios"><summary>Другой исход демо-оплаты</summary><label for="scenario">Учебный ответ оплаты</label><select id="scenario" data-field="scenario">${[['success','Успех'],['declined','Отклонено'],['pending','Результат неизвестен'],['issuance','Оплачено, выдача задержана'],['partial','Оплачено, готова часть билетов'],['offline','Связь потеряна после начала']].map(([v,l])=>`<option value="${v}" ${v===scenario?'selected':''}>${l}</option>`).join('')}</select></details></section>`;
}
function ticketCards(o){return VPC.issuedItems(o).map(t=>`<article class="demo-ticket"><div class="ticket-top"><span>VICTORY PARK</span><strong>ОБРАЗЕЦ</strong></div><h3>${esc(t.name)}</h3><p><strong>${esc(t.recipientLabel)}</strong></p><p>${esc(t.validity)}</p>${t.validUntil?`<p>Использовать до ${esc(new Intl.DateTimeFormat('ru-RU',{dateStyle:'long',timeStyle:'short',timeZone:t.timeZone||'Asia/Yerevan'}).format(new Date(t.validUntil)))} по времени Еревана.</p>`:''}<p>${t.remaining===null?'Повторы без лимита на включённых аттракционах':t.remaining+' прав на катания'}</p><p class="helper">${t.includedNames.map(esc).join(' · ')}</p><details><summary>Условия этого образца</summary><ul>${t.terms.map(s=>'<li>'+esc(s)+'</li>').join('')}</ul></details><p class="ticket-code">${esc(t.code)}</p><p class="ticket-demo">Не действует для прохода. Деньги не списывались.</p></article>`).join('');}
function receipt(){
 const ready=VPC.issuedItems(order),count=order.lines.reduce((n,l)=>n+l.quantity,0);
 const labels={success:['Ваши билеты готовы','Учебная оплата завершена. Все образцы доступны сразу.'],declined:['Оплата не завершена','В учебном сценарии получен окончательный отказ. Состав заказа сохранён.'],pending:['Проверяем оплату','Результат пока неизвестен. Не оплачивайте повторно.'],issuance:['Оплачено. Готовим билеты','Повторно платить не нужно. Проверяйте готовность этого заказа.'],partial:[`Оплачено. Готово ${ready.length} из ${count} билетов`,'Готовые образцы доступны ниже. Остальные ещё выпускаются. Повторно платить не нужно.']};
 const waiting=['pending','issuance','partial'].includes(order.status);
 return `<section class="receipt" id="receipt"><span class="badge" data-tone="demo">Демонстрация · ${esc(order.id)}</span><h1 id="result-heading" tabindex="-1">${labels[order.status][0]}</h1><p>${labels[order.status][1]}</p>${waiting?`<div class="btn-row receipt-actions">${btn('resolve-order',order.status==='pending'?'Проверить статус':'Проверить готовность','','btn btn-primary')}${btn('save-access','Сохранить доступ к заказу','','btn btn-outline')}</div>`:''}${orderTotals(order)}<ul class="receipt-lines">${order.lines.map(l=>`<li>${esc(l.name)} × ${l.quantity}${l.personId||l.productId==='unlimited'?' · '+esc(l.recipientLabel):''}</li>`).join('')}</ul><div class="total"><span>Сумма заказа</span><strong>${money(order.total)}</strong></div>
 ${ready.length?`${btn('save-tickets',order.status==='success'?'Сохранить все билеты':'Сохранить готовые билеты','','btn btn-primary')}<p class="helper">Один HTML-файл открывается без интернета. Образцы не действуют для прохода.</p><p class="receipt-instruction">${order.lines.some(l=>l.productId==='unlimited')?'В учебной модели код безлимита обменивается в демонстрационной кассе на личный носитель. Реальная выдача не подключена.':'Откройте сохранённый файл, чтобы увидеть билеты и их условия. Реальное предъявление в парке пока не подключено.'}</p><div class="demo-ticket-grid">${ticketCards(order)}</div><details class="copy-section" id="copy-section"><summary>Получить копию на почту</summary><p>Чтобы открыть покупку на другом устройстве. Необязательно. Здесь письмо не отправляется, адрес не сохраняется.</p><form id="copy-form" novalidate><div class="field"><label for="copy-email">Электронная почта</label><input type="email" id="copy-email" name="email" inputmode="email" autocomplete="email" aria-describedby="copy-status"></div><button class="btn btn-outline" type="submit">Проверить получение копии</button><p id="copy-status" role="status">${esc(copyStatus)}</p></form><details><summary>Исход демонстрации копии</summary><label for="copy-scenario">Учебный ответ</label><select id="copy-scenario" data-field="copy-scenario"><option value="success" ${!copyFailure?'selected':''}>Проверка завершена</option><option value="failure" ${copyFailure?'selected':''}>Ошибка отправки</option></select></details></details>`:''}
 <div class="btn-row receipt-actions">${!waiting?btn('new-order',viewingHistory?'Вернуться к новой покупке':order.status==='declined'?'Вернуться к заказу':'Собрать другой заказ','','btn btn-outline'):''}<a class="btn btn-text" href="${pickerReturn()}">К нашим аттракционам</a></div>
 ${order.status==='pending'?`<details class="demo-scenarios"><summary>Демо-ответ проверки</summary><label for="resolve-scenario">Следующий статус</label><select id="resolve-scenario" data-field="resolve-scenario">${[['issuance','Оплачено, выдача задержана'],['declined','Окончательный отказ'],['pending','Всё ещё неизвестен']].map(([v,l])=>`<option value="${v}" ${resolveScenario===v?'selected':''}>${l}</option>`).join('')}</select></details>`:''}
 <p class="helper">${storageAvailable?'Заказ сохранён в этом браузере. На другом устройстве нужны сохранённые файлы.':'Сохранение в браузере недоступно. Сохраните доступ и готовые образцы сейчас.'}</p>
 <details class="purchase-help" id="purchase-help"><summary>Нужна помощь с покупкой?</summary><p>Номер учебного заказа: <strong>${esc(order.id)}</strong></p><p>При неизвестном статусе не создавайте новый платёж. Сохраните доступ и вернитесь к проверке этого заказа.</p><p>Поддержка и возвраты в прототипе не подключены. В реальной покупке здесь будут контакт парка, проверка владения покупкой и условия возврата.</p></details></section>`;
}

function companyData(){try{return JSON.parse(localStorage.getItem(COMPANY)||'null');}catch{return null;}}
function companyContext(){
 const applied=companyData()?.lastApplied;if(!applied)return null;
 const clean=VP3.sanitizeState(state),changed=applied.partyFingerprint!==JSON.stringify(clean.party)||(Object.hasOwn(applied,'companionId')&&applied.companionId!==(clean.companionId||null));
 return {applied,changed,matching:applied.cartFingerprint===JSON.stringify(clean.cart.lines)};
}
function clearCompanyApplication(){const data=companyData();if(!data?.lastApplied)return;delete data.lastApplied;try{localStorage.setItem(COMPANY,JSON.stringify(data));}catch{}}
function companySummary(){
 const ctx=companyContext();if(!ctx||(!ctx.changed&&!ctx.matching))return '';
 return `<section class="company-order-summary" id="company-order-summary"><h3>Состав расчёта для компании</h3>${ctx.changed?'<p class="offer-exclusions">Компания изменилась. Пересчитайте выбранный состав: права пакета и сопровождение могут измениться.</p>':'<ul>'+ (Array.isArray(ctx.applied.summary)?ctx.applied.summary:[]).filter(x=>typeof x==='string'&&!/^(Все права:|Срок )/.test(x)).concat(VPC.validitySummary(state.cart.lines,promotion)).map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>'}<a class="btn btn-outline" href="company.html">${ctx.changed?'Пересчитать для компании':'Изменить расчёт'}</a></section>`;
}
function purchaseRouteNotice(){
 const real=deepRide&&!deepRide.fictional;
 return `<section class="empty purchase-route-notice" id="purchase-route-notice" tabindex="-1"><h1>${real?esc(deepRide.name):'Не удалось открыть покупку'}</h1><p>${real?'Для этого настоящего аттракциона цена и онлайн-продукт пока не подтверждены. Купить его в прототипе нельзя.':'В ссылке указан неизвестный аттракцион или продукт. Выбор и заказ сохранены.'}</p>${real?'<p>Учебные билеты относятся к демонстрации и не действуют на этот аттракцион.</p>':''}<div class="btn-row"><a class="btn btn-primary" href="attractions.html?mode=${real?'real':'demo'}${real?'&ride='+encodeURIComponent(deepRide.id):'#catalog'}">${real?'К аттракциону':'Открыть каталог'}</a><a class="btn btn-outline" href="tickets.html?product=single${real?'&from=real':''}">Открыть учебную демонстрацию покупки</a>${state.cart.lines.length?'<a class="btn btn-text" href="tickets.html?product=single#cart">К сохранённому учебному заказу</a>':''}</div></section>`;
}
function focusProduct(){
 if(quick){window.scrollTo({top:0});return;}
 const target=purchaseRouteIssue?'purchase-route-notice':deepRide?.fictional?'product-'+deepRide.id:activeProduct==='single'?'direct':'product-'+activeProduct;
 const el=document.getElementById(target);if(!el)return;if(!el.hasAttribute('tabindex'))el.setAttribute('tabindex','-1');el.scrollIntoView({block:'start',behavior:'auto'});el.focus({preventScroll:true});
}
function renderTickets(){
 if(quick)return renderQuick();
 if(order)return checkoutSwitch()+receipt();
 if(purchaseRouteIssue)return purchaseRouteNotice()+purchases();
 if(reviewing)return `<div class="review-page">${btn('back-to-products','← Изменить выбор','','btn btn-text')}<h1 id="review-heading" tabindex="-1">Проверьте состав</h1>${cart()}</div>`;
 const summary=state.cart.lines.length?cart():undo?.kind==='cart'?`<div class="empty-cart-undo" id="cart">${undoBanner()}<p>В заказе пока нет билетов. Выберите катания ниже.</p></div>`:'';
 if(directEntry)return `<div class="checkout-flow">${checkoutSwitch()}<section class="direct-entry-head checkout-heading"><a class="btn btn-text" href="${pickerReturn()}">← К нашим аттракционам</a><h1>Выберите билеты</h1></section>${purchases()}${savedContext()}${summary}<div class="purchase-options">${directProducts()}</div>${demoTools()}</div>`;
 if(state.mode==='real')return `${hero('tickets')}<section class="empty"><h2>Ваш список сохранён</h2><p>Для настоящих аттракционов онлайн-продукты и правила пока не подтверждены.</p><a class="btn btn-outline" href="attractions.html#plan">Вернуться к списку</a></section>${demoTools()}`;
 return `<div class="checkout-flow">${checkoutSwitch()}<div class="checkout-heading"><a class="btn btn-text" href="attractions.html#plan">← К нашим аттракционам</a><h1>Выберите билеты</h1><p>Учебная покупка. Деньги не списываются.</p></div>${purchases()}${riderPicker()}${summary}${selected().length?`<p class="saved-summary">В вашем списке: ${selected().map(rid=>esc(ride(rid)?.name)).join(' · ')}. <a href="attractions.html#plan">Изменить</a></p>`:''}${recommendations()}<details class="self-choice" id="self-choice"><summary>Выбрать другие билеты, пакет или безлимит</summary>${directProducts()}</details>${demoTools()}</div>`;
}

function render(){syncCompanions();if(reviewing&&!state.cart.lines.length){reviewing=false;reviewedToken='';requestAnimationFrame(()=>jump(directEntry?'#direct':'#recommendations'));}if(!order)save();if(!person(ticketPersonId)){const selectedPeople=state.riders.map(person).filter(Boolean),children=state.party.filter(p=>p.role==='child');ticketPersonId=(selectedPeople.length===1?selectedPeople[0]:state.party.length===1?state.party[0]:children.length===1?children[0]:null)?.id||'';}const active=document.activeElement,activeId=active?.id,ds=active?.dataset?{...active.dataset}:null;const openIds=[...document.querySelectorAll('#app details[open]')].map(d=>d.id).filter(x=>x&&x!=='family');document.body.dataset.mode=state.mode;document.body.classList.toggle('family-editing',document.body.dataset.page==='picker'&&familyOpen);$('#app').innerHTML=(warning?note(warning,'error'):'')+(state.tariffNotice&&!order?note(state.tariffNotice,'warning'):'')+(state._issues?.length?note('Сохранённые данные частично повреждены. Проверьте семью и заказ; при необходимости очистите выбор в описании прототипа.','error'):'')+(document.body.dataset.page==='picker'?renderPicker():renderTickets());for(const did of openIds){const d=document.getElementById(did);if(d)d.open=true;}$('#family')?.addEventListener('toggle',e=>{if(e.target.isConnected){familyOpen=e.target.open;document.body.classList.toggle('family-editing',document.body.dataset.page==='picker'&&familyOpen);}});const count=state.cart.lines.reduce((n,l)=>n+l.quantity,0);if($('#cart-count'))$('#cart-count').textContent=count?' ('+count+')':'';document.querySelectorAll('[data-mobile-cart-count]').forEach(el=>el.textContent=count?' ('+count+')':'');$('#app').setAttribute('aria-busy',String(busy));$('#mobile').innerHTML=busy?'<div class="mobile-bar checkout-dock"><div><strong>Проверяем оплату</strong><small>Учебный ответ</small></div><button class="btn btn-primary" disabled>Подождите</button></div>':order?'':document.body.dataset.page==='tickets'?checkoutBar():`<div class="mobile-bar"><div><strong>${selected().length} в списке</strong></div><a class="btn btn-primary" href="#plan">Наш список</a></div>`;if(quick&&needsProductChoice&&!order){$('#mobile').innerHTML='';}else if(document.body.dataset.page==='tickets'&&purchaseRouteIssue&&!order){$('#mobile').innerHTML='';}else if(document.body.dataset.page==='tickets'&&state.mode==='real'&&!order){$('#mobile').innerHTML='<div class="mobile-bar"><div><strong>Список сохранён</strong><small>Настоящие аттракционы</small></div><a class="btn btn-primary" href="attractions.html#plan">К списку</a></div>';}if(activeId&&document.getElementById(activeId))document.getElementById(activeId).focus({preventScroll:true});else if(ds?.action){const match=[...document.querySelectorAll('[data-action]')].find(el=>Object.entries(ds).every(([k,v])=>el.dataset[k]===v));match?.focus({preventScroll:true});}document.dispatchEvent(new Event('vp:catalog-rendered'));}
function addPerson(role){if(state.party.length>=8)return;const p={id:id(),label:(role==='adult'?'Взрослый ':'Ребёнок ')+(Math.max(0,...state.party.filter(p=>p.role===role).map(p=>Number(p.label.match(/\d+$/)?.[0])||0))+1),role,age:role==='adult'?18:null,height:null};state.party.push(p);familyOpen=true;agePerson=role==='child'?p.id:'';update();requestAnimationFrame(()=>$('#person-'+p.id)?.scrollIntoView({block:'nearest',behavior:'smooth'}));}
function clearIssues(){state._issues=[];formError='';}
function commitCart(lines,message,reveal=true){undo={kind:'cart',message:'Заказ изменён.',lines:clone(state.cart.lines),company:companyData()};clearCompanyApplication();state.cart={lines};clearIssues();update(message);if(reveal&&state.cart.lines.length&&!customTarget)requestAnimationFrame(()=>focusField('cart'));}
function setQuantity(target,n){
 if(target.startsWith('quick:'))return setQuickQuantity(target,n);
 if(!Number.isInteger(n)||n<1||n>20)return false;
 const lines=clone(state.cart.lines);
 if(target.startsWith('line:')){const line=lines.find(l=>l.id===target.slice(5));if(!line||VP3.isPackage(line)||line.productId==='unlimited'||line.autoCompanion)return false;line.quantity=n;}
 else if(target.startsWith('ticket:')){if(!person(ticketPersonId))return false;const rid=target.slice(7),r=ride(rid);if(!r?.fictional)return false;const line=lines.find(l=>!l.autoCompanion&&l.productId==='ticket'&&l.rideId===rid&&l.personId===ticketPersonId);if(line)line.quantity=n;else lines.push({id:id(),productId:'ticket',rideId:rid,personId:ticketPersonId,recipientKey:null,quantity:n,unitPrice:r.price});}
 else return false;
 customTarget='';commitCart(lines,'Состав и сопровождение пересчитаны.',!quick&&!target.startsWith('line:'));return true;
}
function directPass(pId){if(!state.riders.includes(pId))state.riders.push(pId);ticketPersonId=pId;const current=state.cart.lines.find(l=>l.productId==='unlimited'&&l.personId===pId);if(current&&isRequiredLine(current))return;if(person(pId)?.role==='child'&&person(pId).age===null)agePerson=pId;commitCart(current?state.cart.lines.filter(l=>l.id!==current.id):[...state.cart.lines,{id:id(),productId:'unlimited',rideId:null,personId:pId,recipientKey:null,quantity:1,unitPrice:VP3.products.unlimited.price}],current?'Безлимит удалён.':'Безлимит и необходимое сопровождение добавлены.',false);}
function purchaseAdd(role,companion=false){if(state.party.length>=8)return;const p={id:id(),label:(role==='adult'?'Взрослый ':'Ребёнок ')+(Math.max(0,...state.party.filter(x=>x.role===role).map(x=>Number(x.label.match(/\d+$/)?.[0])||0))+1),role,age:role==='adult'?18:null,height:null};state.party.push(p);if(companion){state.companionId=p.id;update('Взрослый добавлен для сопровождения.');jump('#companion-controls');return;}ticketPersonId=p.id;agePerson=role==='child'?p.id:'';const missing=state.cart.lines.filter(l=>!VP3.isPackage(l)&&!VP3.isDirectLine(l)&&!l.personId);if(missing.length===1)missing[0].personId=p.id;else if(activeProduct==='unlimited'){state.cart.lines.push({id:id(),productId:'unlimited',rideId:null,personId:p.id,recipientKey:null,quantity:1,unitPrice:VP3.products.unlimited.price});if(!state.riders.includes(p.id))state.riders.push(p.id);}update('Получатель добавлен.');jump('#purchase-people');}
async function pay(){if(busy||order||(!quick&&needsReview()&&!reviewing)||companyContext()?.changed)return;if(!navigator.onLine){formError='Нет связи. Подключитесь к интернету и попробуйте оплатить снова. Платёж не начат.';render();focusField('checkout-errors');return;}const a=calculateCart(state,promotion);if(!a.canCheckout){formError='Проверьте состав и получателей заказа.';render();jump('#checkout-errors');return;}busy=true;render();const run=async()=>{try{const other=VPC.validateOrder(JSON.parse(localStorage.getItem(ORDER)||'null'));if(other&&!['success','declined'].includes(other.status)){order=other;busy=false;render();return;}}catch{}order=VPC.snapshotOrder(state,promotion,'DEMO-'+id(),'pending',undefined,purchaseOptions);if(!order){busy=false;formError='Не удалось создать образец. Проверьте заказ.';render();return;}saveOrder();render();await new Promise(resolve=>setTimeout(resolve,300));const confirmed=VPC.confirmPayment(order,!navigator.onLine||scenario==='offline'?'pending':scenario);if(!confirmed){busy=false;warning='Не удалось проверить ответ оплаты. Повторно не оплачивайте; проверьте сохранённый заказ.';render();return;}order=confirmed;saveOrder();busy=false;render();window.scrollTo({top:0});$('#result-heading')?.focus({preventScroll:true});announce('Статус заказа обновлён.');};try{if(navigator.locks?.request)await navigator.locks.request(LOCK,run);else{busy=false;formError='В этом браузере недоступна защита заказа между вкладками. Откройте прототип в современном браузере.';render();}}catch{busy=false;warning='Не удалось завершить проверку. Если заказ создан, проверяйте его статус.';render();}}
function saveTickets(){if(!order||!['success','partial'].includes(order.status))return;const html=`<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Демо-билеты ${esc(order.id)}</title><style>body{font:16px/1.5 Arial,sans-serif;color:#2f2e7d;max-width:850px;margin:24px auto;padding:20px}h1{font-size:30px}h3{font-size:22px}.demo-ticket{border:2px solid #2f2e7d;border-radius:16px;padding:22px;margin:18px 0;break-inside:avoid}.ticket-top{display:flex;justify-content:space-between;gap:15px;font-size:12px}.ticket-code{font:13px monospace;overflow-wrap:anywhere}.ticket-demo{font-weight:bold}details{margin:14px 0}</style><h1>${order.status==='partial'?'Готовая часть демо-билетов':'Ваши демо-билеты'}</h1>${order.status==='partial'?'<p>Выдана только часть покупки. Остальные билеты проверяйте в исходном заказе.</p>':''}<p>${esc(order.id)} · ${money(order.total)}</p><p>Образцы не действуют для прохода. Деньги не списывались.</p>${ticketCards(order).replaceAll('<details>','<details open>')}${orderTotals(order)}<p>Учебные условия, не утверждённая оферта парка.</p></html>`;const url=URL.createObjectURL(new Blob([window.VPI18n ? VPI18n.translateHTML(html) : html],{type:'text/html;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=order.id+'-tickets.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);announce(order.status==='success'?'Полный комплект подготовлен для сохранения.':'Готовая часть билетов подготовлена для сохранения.');}
function saveAccess(){
 if(!order)return;
 const url=location.origin+location.pathname+'?resume='+encodeURIComponent(order.id)+'&lang='+(window.VPI18n?.language||'ru');
 const html=`<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Доступ к учебному заказу</title><body><h1>Учебный заказ ${esc(order.id)}</h1><p>Сумма: ${money(order.total)}</p><p>Это сохранённые данные, а не актуальная проверка платежа. Реальных списаний не было.</p><p><a href="${esc(url)}">Проверить заказ в исходном браузере</a></p><p>Ссылка работает только в браузере, где сохранён заказ. На другом устройстве этот файл не восстанавливает покупку.</p><ul>${order.lines.map(l=>`<li>${esc(l.name)} × ${l.quantity}: ${esc(l.recipientLabel)}</li>`).join('')}</ul></body></html>`;
 const objectUrl=URL.createObjectURL(new Blob([window.VPI18n ? VPI18n.translateHTML(html) : html],{type:'text/html;charset=utf-8'}));const a=document.createElement('a');a.href=objectUrl;a.download=order.id+'-access.html';a.click();setTimeout(()=>URL.revokeObjectURL(objectUrl),1000);announce('Данные заказа подготовлены для сохранения.');
}
document.addEventListener('click',e=>{if(busy){e.preventDefault();e.stopImmediatePropagation();return;}const switcher=e.target.closest('[data-checkout-switch]');if(switcher){try{const raw=JSON.stringify(state);localStorage.setItem(KEY,raw);if(localStorage.getItem(KEY)!==raw)throw new Error('storage');}catch{e.preventDefault();warning='Не удалось сохранить выбор. Оставайтесь на этой странице, чтобы завершить покупку.';render();}return;}const detail=e.target.closest('[data-open-details]');if(detail){e.preventDefault();const d=$('#details-'+detail.dataset.openDetails);if(d){d.open=true;jump('#details-'+detail.dataset.openDetails);}return;}const b=e.target.closest('[data-action]');if(!b)return;const act=b.dataset.action;if(busy)return;
if(act==='recalculate-company'){location.href=checkoutRoute('company.html');return;}
if(act==='review-order'){reviewOrder();return;}
if(act==='back-to-products'){reviewing=false;reviewedToken='';render();jump(directEntry?'#direct':'#recommendations');return;}
if(act==='fix-order'){focusField(b.dataset.target);return;}
if(act==='show-products'){if(b.dataset.target){focusField(b.dataset.target);return;}if(!directEntry&&!state.riders.length&&state.party.length){focusField('riders');return;}if(!directEntry&&state.riders.length){focusField('recommendations');return;}focusField('direct');return;}
if(act==='edit-riders'){state.ridersConfirmed=false;update();jump('#riders');return;}
if(act==='ticket-person'){ticketPersonId=b.dataset.person;agePerson=person(ticketPersonId)?.age===null&&person(ticketPersonId)?.role==='child'?ticketPersonId:'';render();return;}
if(act==='purchase-add-adult'||act==='purchase-add-child'||act==='purchase-add-companion'){purchaseAdd(act==='purchase-add-child'?'child':'adult',act==='purchase-add-companion');return;}
if(act==='edit-companion'){editingCompanion=true;render();focusField('companion-controls');return;}
if(act==='choose-companion'){editingCompanion=false;state.companionId=b.dataset.person;state.companionAutoSelected=false;clearIssues();update('Сопровождающий выбран для всего заказа.');return;}
if(act==='make-direct-line'){
 if(!quick)return;
 const lines=clone(state.cart.lines),line=lines.find(l=>l.id===b.dataset.line);
 if(!line||line.personId||line.autoCompanion||!['ticket','unlimited'].includes(line.productId)||VP3.isDirectLine(line))return;
 line.recipientKey=(line.productId==='unlimited'?'direct-pass-':'direct-ticket-')+id();
 activeProduct=line.productId==='unlimited'?'unlimited':'single';if(line.productId==='ticket'){quickRideId=line.rideId;quickPersonId='';}
 commitCart(lines,'Билеты сохранены без назначения получателя. Количество и сумма не изменились.',false);return;
}
if(act==='assign-line-person'){const line=state.cart.lines.find(l=>l.id===b.dataset.line);if(line){line.personId=b.dataset.person;line.recipientKey=null;ticketPersonId=b.dataset.person;if(person(ticketPersonId)?.role==='child'&&person(ticketPersonId).age===null)agePerson=ticketPersonId;clearIssues();update('Получатель выбран. Сопровождение пересчитано.');}return;}
if(act==='add-adult'||act==='add-child'){addPerson(act==='add-adult'?'adult':'child');return;}
if(act==='collapse-family'){agePerson='';familyOpen=false;render();jump('#catalog');return;}
if(act==='edit-age'){agePerson=agePerson===b.dataset.person?'':b.dataset.person;render();if(agePerson)requestAnimationFrame(()=>$('#person-'+agePerson)?.scrollIntoView({block:'nearest',behavior:'smooth'}));return;}
if(act==='choose-age'){const p=person(b.dataset.person);if(!p||p.role!=='child')return;const value=b.dataset.value;if(value!=='unknown'&&(!Number.isInteger(Number(value))||Number(value)<0||Number(value)>17))return;p.age=value==='unknown'?null:Number(value);agePerson='';clearIssues();update('Возраст сохранён.');$('#age-'+p.id)?.focus({preventScroll:true});return;}
if(act==='remove-person'){undo={kind:'person',message:'Участник удалён.',state:clone(state)};const pid=b.dataset.person;if(agePerson===pid)agePerson='';state.party=state.party.filter(p=>p.id!==pid);state.riders=state.riders.filter(x=>x!==pid);state.cart.lines=state.cart.lines.filter(l=>l.personId!==pid);if(!state.riders.length)state.ridersConfirmed=false;clearIssues();update('Участник и его личные товары удалены. Можно отменить.');return;}
if(act==='focus-person'){focusPerson=b.dataset.person;render();return;}
if(act==='toggle-ride'){const rid=b.dataset.ride,ids=selected(),exists=ids.includes(rid);undo=exists?{kind:'ride',message:'Аттракцион удалён из списка.',ride:rid,mode:state.mode}:null;state.selections[state.mode]=exists?ids.filter(x=>x!==rid):[...ids,rid];update(exists?'Удалено. Можно отменить.':'Сохранено в нашем списке.');return;}
if(act==='mode'){state.mode=b.dataset.mode;focusPerson='family';undo=null;update('Набор данных изменён. Ваши списки сохранены отдельно.');return;}
if(act==='sample'){undo={kind:'sample',message:'Загружен пример. Свой выбор можно вернуть.',state:clone(state),promotion:clone(promotion)};promotion=VPC.normalizePromotion(null);savePromotion();state=VP3.sampleState();familyOpen=false;agePerson='';focusPerson='family';update('Загружен пример.');return;}
if(act==='reset-state'){undo={kind:'reset',message:'Выбор очищен.',state:clone(state),promotion:clone(promotion)};promotion=VPC.normalizePromotion(null);savePromotion();clearCompanyApplication();state=VP3.emptyState();familyOpen=true;agePerson='';update('Выбор очищен. Можно отменить.');return;}
if(act==='undo'){if(!undo)return;if(undo.kind==='ride')state.selections[undo.mode]=[...new Set([...state.selections[undo.mode],undo.ride])];else if(undo.kind==='cart'){state.cart.lines=undo.lines;if(undo.company)try{localStorage.setItem(COMPANY,JSON.stringify(undo.company));}catch{}}else if(undo.state)state=undo.state;if(undo.promotion){promotion=undo.promotion;savePromotion();}undo=null;update('Изменение отменено.');return;}
if(act==='rider'){const pid=b.dataset.person;state.riders=state.riders.includes(pid)?state.riders.filter(x=>x!==pid):[...state.riders,pid];state.ridersConfirmed=state.riders.length>0;update('Катающиеся изменены. Состав уже выбранного заказа можно проверить ниже.');return;}
if(act==='confirm-riders'){if(!state.riders.length)return;state.ridersConfirmed=true;update();jump('#recommendations');return;}
if(act==='choose-offer'){const offer=VP3.recommend({...state,ridersConfirmed:state.riders.length>0}).offers.find(o=>o.id===b.dataset.offer);if(offer&&!offer.alreadyAdded&&!offer.unavailable){commitCart(clone(offer.lines),offer.mode==='add'?'Добавлено в заказ.':'Заказ заменён. Можно отменить.');}return;}
if(act==='fix-recipient'){reviewing=false;activeProduct=b.dataset.product;render();jump('#purchase-people');return;}
if(act==='product-focus'){needsProductChoice=false;activeProduct=b.dataset.product;customTarget='';deepRide=null;params.delete('ride');if(directEntry){params.set('product',activeProduct);try{history.replaceState({...history.state,vp3scroll:0},'',location.pathname+'?'+params.toString());}catch{}}render();return;}
if(act==='package-size'){choosePackage(b.dataset.product);return;}
if(act==='quantity'){setQuantity(b.dataset.target,Number(b.dataset.value));return;}
if(act==='custom-quantity'){customTarget=b.dataset.target;render();const input=$('#custom-quantity');input?.focus();input?.select();return;}
if(act==='remove-line'){const current=state.cart.lines.find(l=>l.id===b.dataset.line);if(current&&isRequiredLine(current))return;commitCart(state.cart.lines.filter(l=>l.id!==b.dataset.line),'Товар удалён. Можно отменить.');return;}
if(act==='direct-pass'){directPass(b.dataset.person);return;}
if(act==='promo-date'){promotion.visitDate=b.dataset.date;savePromotion();render();focusField('cart-visit-date');return;}
if(act==='promo-fix'){if(b.dataset.target==='direct'){reviewing=false;const product=VPO.getOffer(promotion.offerId)?.productIds[0];activeProduct=VP3.isPackage(product)?'package':product==='unlimited'?'unlimited':'single';render();}focusField(b.dataset.target);return;}
if(act==='remove-promotion'){promotion.offerId=null;savePromotion();render();announce('Предложение убрано. Все билеты сохранены.');return;}
if(act==='pay'){if(e.detail>1)return;pay();return;}
if(act==='save-tickets'){saveTickets();return;}
if(act==='resolve-order'){if(!order||!['pending','issuance','partial'].includes(order.status))return;if(!navigator.onLine){warning='Нет связи. Статус заказа не изменён. Повторите проверку после подключения.';render();return;}warning='';const confirmed=VPC.confirmPayment(order,order.status==='pending'?resolveScenario:'success');if(!confirmed){warning='Не удалось проверить ответ. Сохранённый заказ остаётся доступен; повторно не оплачивайте.';render();return;}order=confirmed;saveOrder();render();announce('Обновлён тот же демо-заказ.');return;}
if(act==='open-order'){if(order)return;const saved=pastOrders().find(o=>o.id===b.dataset.order);if(saved){order=saved;viewingHistory=true;settlePaidLines(saved);orderURL(saved.id);copyStatus='';render();focusField('result-heading');}return;}
if(act==='save-access'){saveAccess();return;}
if(act==='new-order'){orderURL(null);if(viewingHistory){viewingHistory=false;const active=storedOrder();settlePaidLines(active);order=active&&!['success','declined'].includes(active.status)?active:null;render();return;}reviewing=false;reviewedToken='';copyStatus='';if(order?.status==='success'){if(!saveOrder()){render();announce('Не удалось сохранить покупку в истории. Билеты остаются открыты.');return;}undo=null;settlePaidLines(order);state.tariffNotice=null;clearCompanyApplication();promotion=VPC.normalizePromotion(null);savePromotion();}order=null;saveOrder();if(directEntry)state.mode='demo';clearIssues();update();if(directEntry)jump('#direct');return;}
});
document.addEventListener('change',e=>{const el=e.target,field=el.dataset.field;if(field==='quick-ride'){quickRideId=el.value;customTarget='';render();return;}if(field==='quick-person'){quickPersonId=person(el.value)?.id||'';customTarget='';render();return;}if(field==='scenario'){scenario=el.value;return;}if(field==='copy-scenario'){copyFailure=el.value==='failure';return;}if(field==='resolve-scenario'){resolveScenario=el.value;return;}if(['promotion','visit-date','student'].includes(field)){if(field==='promotion'){const next=el.value==='none'?null:el.value;if(next!==promotion.offerId)promotion.studentAcknowledged=false;promotion.offerId=next;}if(field==='visit-date')promotion.visitDate=el.value||null;if(field==='student')promotion.studentAcknowledged=el.checked;savePromotion();render();announce('Предложение сохранено. Состав заказа не изменён.');return;}if(field!=='height')return;const p=person(el.dataset.person);if(!p)return;const raw=el.value.trim().replace(',','.'),n=Number(raw),valid=raw===''||(/^\d+(\.\d+)?$/.test(raw)&&n>=40&&n<=250);const error=document.getElementById(el.getAttribute('aria-describedby'))||document.getElementById('height-error-'+el.dataset.ride+'-'+p.id);if(!valid){el.setAttribute('aria-invalid','true');if(error)error.textContent='Укажите рост от 40 до 250 см или оставьте пустым.';return;}p.height=raw===''?null:n;el.removeAttribute('aria-invalid');if(error)error.textContent='';clearIssues();update('Рост сохранён. Условия и цена пересчитаны.');});
document.addEventListener('submit',e=>{const f=e.target;if(f.matches('.custom-quantity-form')){e.preventDefault();const input=f.elements.quantity,target=f.dataset.target,raw=input.value.trim(),n=Number(raw);if(!/^\d+$/.test(raw)||!setQuantity(target,n)){$('#quantity-error').textContent='Введите целое число от 1 до 20. Заказ не изменён.';input.setAttribute('aria-invalid','true');input.focus({preventScroll:true});}else{requestAnimationFrame(()=>{const action=n>4?'custom-quantity':'quantity';const control=[...document.querySelectorAll('[data-action]')].find(el=>el.dataset.action===action&&el.dataset.target===target&&(n>4||Number(el.dataset.value)===n));control?.focus({preventScroll:true});});}return;}if(f.id==='direct-person-form'){e.preventDefault();const name=f.elements.name.value.trim();if(!name){$('#recipient-error').textContent='Укажите имя получателя.';return;}if(state.party.some(p=>p.label.toLocaleLowerCase()===name.toLocaleLowerCase())){$('#recipient-error').textContent='Такой участник уже есть. Выберите его выше.';return;}if(state.party.length>=8){$('#recipient-error').textContent='В прототипе до восьми участников. Выберите существующего.';return;}const p={id:id(),label:name,role:f.elements.role.value==='child'?'child':'adult',age:null,height:null};state.party.push(p);directPass(p.id);return;}if(f.id==='copy-form'){e.preventDefault();const input=$('#copy-email');if(!input.value.trim()||!input.checkValidity()){copyStatus='Проверьте адрес электронной почты.';$('#copy-status').textContent=copyStatus;input.setAttribute('aria-invalid','true');input.focus();return;}input.removeAttribute('aria-invalid');copyStatus=copyFailure?'Не удалось отправить копию (учебный сценарий). Билеты доступны выше. Попробуйте снова.':'Проверка завершена. В прототипе письмо не отправлено, адрес не сохранён. Билеты доступны выше.';$('#copy-status').textContent=copyStatus;input.value='';}});
window.addEventListener('storage',e=>{if(e.key===COMPANY&&!busy)render();if(e.key===PROMO&&!busy){try{promotion=VPC.normalizePromotion(JSON.parse(e.newValue||'null'));render();}catch{}}if(e.key===KEY&&!busy){try{state=VP3.sanitizeState(JSON.parse(e.newValue||'null'));undo=null;render();announce('Выбор обновлён в другой вкладке.');}catch{}}if(e.key===ORDER){try{if(!viewingHistory)order=VPC.validateOrder(JSON.parse(e.newValue||'null'));render();}catch{}}});
window.addEventListener('pagehide',()=>{try{history.replaceState({...history.state,vp3scroll:window.scrollY,vp3Mode:state.mode},'');}catch{}});
window.addEventListener('pageshow',e=>{if(e.persisted){try{promotion=VPC.normalizePromotion(JSON.parse(localStorage.getItem(PROMO)||'null'));state=VP3.sanitizeState(JSON.parse(localStorage.getItem(KEY)||'null'));restoreOrderView();if(document.body.dataset.page==='picker'&&['real','demo'].includes(history.state?.vp3Mode))state.mode=history.state.vp3Mode;if(document.body.dataset.page==='tickets'&&directEntry&&!order)state.mode='demo';save();render();}catch{}}});
const params=new URLSearchParams(location.search);
// Keep the URL's locale current when product navigation reuses these parameters.
document.addEventListener('vp:language',e=>params.set('lang',e.detail.language));
// A neutral entry resumes the draft product without adding or replacing cart lines.
const draftProductLine=!params.has('product')&&!params.has('ride')?[...state.cart.lines].reverse().find(l=>!l.autoCompanion):null;
needsProductChoice=quick&&!params.has('product')&&!params.has('ride')&&!params.has('resume')&&!draftProductLine&&!state.cart.lines.length;
if(draftProductLine)activeProduct=VP3.isPackage(draftProductLine)?'package':draftProductLine.productId==='unlimited'?'unlimited':'single';
if(params.has('product'))activeProduct=['single','package','unlimited'].includes(params.get('product'))?params.get('product'):'single';if(location.hash==='#family')familyOpen=true;if(document.body.dataset.page==='picker'&&['real','demo'].includes(params.get('mode'))){state.mode=params.get('mode');save();}let deepRide=ride(params.get('ride'));if(deepRide){state.mode=deepRide.fictional?'demo':'real';save();}
if(document.body.dataset.page==='tickets'){
 if(params.has('ride')&&!deepRide||params.has('product')&&!['single','package','unlimited'].includes(params.get('product')))purchaseRouteIssue='invalid';
 else if(deepRide&&!deepRide.fictional)purchaseRouteIssue='real-product-unconfirmed';
 else if(deepRide){activeProduct='single';params.set('product','single');}
}
if(document.body.dataset.page==='tickets'){
  if(params.has('offer')){const next=params.get('offer')==='none'?null:params.get('offer');if(next!==promotion.offerId)promotion.studentAcknowledged=false;promotion.offerId=next;}
  if(params.has('date'))promotion.visitDate=params.get('date')||null;
  if(params.has('student'))promotion.studentAcknowledged=params.get('student')==='1';
  if(!order&&!state.cart.lines.length&&params.has('legacyProduct')){
    const product=params.get('legacyProduct'),rid=params.get('legacyRide'),n=Number(params.get('legacyQty'));
    if(['ticket','package5','unlimited'].includes(product)&&Number.isInteger(n)&&n>=1&&n<=20&&(product!=='ticket'||VP3.demoRides.some(r=>r.id===rid))){
      state.cart.lines=Array.from({length:product==='unlimited'?n:1},(_,i)=>({id:id(),productId:product,rideId:product==='ticket'?rid:null,personId:null,recipientKey:product==='unlimited'?'legacy-recipient-'+(i+1):null,quantity:product==='unlimited'?1:n,unitPrice:product==='ticket'?ride(rid).price:VP3.products[product].price}));
      state.mode='demo';save();
    }
  }
  savePromotion();['offer','date','student','legacyProduct','legacyRide','legacyQty'].forEach(k=>params.delete(k));
  try{history.replaceState(history.state,'',location.pathname+(params.size?'?'+params.toString():'')+location.hash);}catch{}
}
if(document.body.dataset.page==='tickets'){directEntry=quick||params.has('product')||params.has('ride')||params.get('from')==='real'||location.hash==='#direct'||state.mode==='real'||!state.party.length;returnMode=params.get('from')==='real'||state.mode==='real'?'real':'';if(directEntry){if(!params.has('product')&&!needsProductChoice)params.set('product',activeProduct);if(returnMode==='real')params.set('from','real');try{history.replaceState(history.state,'',location.pathname+'?'+params.toString()+location.hash);}catch{}if(!order&&!purchaseRouteIssue){state.mode='demo';save();}}}

if(params.has('resume'))restoreOrderView();
window.addEventListener('offline',()=>{warning=order?'Нет связи. Сохранённый статус не обновляется. Повторно не оплачивайте.':'Нет связи. Выбор остаётся в этой вкладке; оплата недоступна.';render();});
window.addEventListener('online',()=>{warning='';render();announce(order?'Связь восстановлена. Проверьте статус заказа.':'Связь восстановлена.');});

const draftTicketLine=!deepRide&&activeProduct==='single'?[...state.cart.lines].reverse().find(l=>l.productId==='ticket'&&!l.autoCompanion):null;
quickRideId=deepRide?.fictional?deepRide.id:draftTicketLine?.rideId||state.selections.demo[0]||VP3.demoRides[0].id;
if(draftProductLine?.personId)ticketPersonId=draftProductLine.personId;
if(draftTicketLine?.personId){ticketPersonId=draftTicketLine.personId;quickPersonId=draftTicketLine.personId;}
render();
if(order&&document.body.dataset.page==='tickets')window.scrollTo({top:0});
else if(history.state?.vp3scroll>0)requestAnimationFrame(()=>window.scrollTo(0,history.state.vp3scroll));
else if(document.body.dataset.page==='tickets'&&(purchaseRouteIssue||directEntry)&&location.hash!=='#cart')requestAnimationFrame(focusProduct);
else if(deepRide){const d=$('#details-'+deepRide.id);if(d)d.open=true;jump('#ride-'+deepRide.id);}
else if(location.hash==='#cart'&&state.cart.lines.length)jump('#cart');else if(location.hash)jump(location.hash);
if(window.visualViewport){const setKeyboard=()=>document.body.classList.toggle('keyboard-open',innerHeight-window.visualViewport.height>150&&/^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement?.tagName||''));window.visualViewport.addEventListener('resize',setKeyboard);document.addEventListener('focusout',()=>requestAnimationFrame(setKeyboard));}
window.VP3UI={getState:()=>clone(state),getOrder:()=>clone(order)};
})();
